import { useCallback, useState } from 'react'

/**
 * Constants
 */
let globalZIndex = 500

/**
 * Main Hook
 */
export function useZIndex(baseZ: number = 500) {
  /**
   * States
   */
  const [zIndex, setZIndex] = useState(baseZ)

  /**
   * Callbacks
   */
  const acquire = useCallback(() => {
    globalZIndex += 2
    setZIndex(globalZIndex)
    return globalZIndex
  }, [])

  const release = useCallback(() => {
    // optional: reduce globalZIndex when releasing
  }, [])

  return { zIndex, acquire, release }
}
