import {
  Children,
  FC,
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useState,
} from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { DropdownItemProps, DropdownMenuProps, DropdownOption } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface DropdownContextValue {
  activeKey: number | null
  direction: 'up' | 'down'
  activeColor?: string
  onToggle: (index: number) => void
  onClose: () => void
  onItemValueChange: (index: number, value: string | number) => void
  itemValues: Record<number, string | number>
}

interface DropdownItemInternalProps extends DropdownItemProps {
  __index?: number
}

/**
 * Context
 */
const DropdownContext = createContext<DropdownContextValue | null>(null)

/**
 * Sub Components
 */
export const DropdownMenu: FC<DropdownMenuProps> = ({
  activeKey,
  defaultActiveKey = null,
  onActiveKeyChange,
  activeColor = 'var(--ct-color-primary)',
  direction = 'down',
  overlay = true,
  closeOnOverlayClick = true,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [currentKey, setCurrentKey] = useControllable({
    value: activeKey,
    defaultValue: defaultActiveKey,
    onChange: onActiveKeyChange,
  })

  /**
   * States
   */
  const [menuTop, setMenuTop] = useState(0)
  const [itemValues, setItemValues] = useState<Record<number, string | number>>({})

  /**
   * Callbacks
   */
  const handleToggle = (index: number) => {
    setCurrentKey(currentKey === index ? null : index)
  }

  const handleClose = () => {
    setCurrentKey(null)
  }

  const handleItemValueChange = (index: number, value: string | number) => {
    setItemValues((prev) => ({ ...prev, [index]: value }))
  }

  const handleOverlayClick = () => {
    if (closeOnOverlayClick) {
      handleClose()
    }
  }

  /**
   * Effects
   */
  useEffect(() => {
    const query = Taro.createSelectorQuery()
    query.select('.ct-dropdown-menu__bar').boundingClientRect()
    query.exec((res) => {
      if (res[0]) {
        setMenuTop(res[0].bottom)
      }
    })
  }, [])

  /**
   * Render Helpers
   */
  const renderChildren = () =>
    Children.map(children, (child, index) => {
      if (isValidElement(child)) {
        return cloneElement(child, { __index: index } as any)
      }
      return child
    })

  return (
    <DropdownContext.Provider
      value={{
        activeKey: currentKey,
        direction,
        activeColor,
        onToggle: handleToggle,
        onClose: handleClose,
        onItemValueChange: handleItemValueChange,
        itemValues,
      }}
    >
      <View className={classNames('ct-dropdown-menu', className)}>
        <View className="ct-dropdown-menu__bar">
          {Children.map(children, (child, index) => {
            if (!isValidElement<DropdownItemProps>(child)) return null

            const { title, options, value, defaultValue, disabled } = child.props
            const isActive = currentKey === index
            const resolvedValue =
              value !== undefined ? value : itemValues[index] ?? defaultValue
            const selectedOption = options.find(
              (option) => option.value === resolvedValue,
            )

            return (
              <View
                key={index}
                className={classNames('ct-dropdown-menu__item', {
                  'ct-dropdown-menu__item--active': isActive,
                  'ct-dropdown-menu__item--disabled': disabled,
                })}
                onClick={() => !disabled && handleToggle(index)}
              >
                <Text
                  className="ct-dropdown-menu__title"
                  style={isActive ? { color: activeColor } : undefined}
                >
                  {title || selectedOption?.text || '请选择'}
                </Text>
                <Icon
                  name={direction === 'down' ? 'chevron-down' : 'chevron-up'}
                  size={24}
                  className={classNames('ct-dropdown-menu__icon', {
                    'ct-dropdown-menu__icon--rotate': isActive,
                  })}
                />
              </View>
            )
          })}
        </View>

        {currentKey !== null && overlay && (
          <View
            className="ct-dropdown-menu__overlay"
            style={{ top: `${menuTop}px` }}
            onClick={handleOverlayClick}
          />
        )}

        <View
          className={classNames('ct-dropdown-menu__content', {
            'ct-dropdown-menu__content--up': direction === 'up',
          })}
          style={direction === 'down' ? { top: `${menuTop}px` } : undefined}
        >
          {renderChildren()}
        </View>
      </View>
    </DropdownContext.Provider>
  )
}

export const DropdownItem: FC<DropdownItemInternalProps> = ({
  value,
  defaultValue,
  options,
  onChange,
  className,
  __index,
}) => {
  /**
   * Hooks
   */
  const context = useContext(DropdownContext)

  const [currentValue, setCurrentValue] = useControllable({
    value,
    defaultValue: defaultValue ?? options[0]?.value,
    onChange,
  })

  /**
   * Early Returns
   */
  if (!context) return null

  /**
   * Derived Values
   */
  const { activeKey, activeColor, itemValues, onClose, onItemValueChange } = context
  const isOpen = activeKey === __index

  /**
   * Callbacks
   */
  const handleSelect = (option: DropdownOption) => {
    if (option.disabled) return
    setCurrentValue(option.value)
    if (__index !== undefined) {
      onItemValueChange(__index, option.value)
    }
    onClose()
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (__index === undefined || value !== undefined) return
    if (currentValue !== undefined && itemValues[__index] !== currentValue) {
      onItemValueChange(__index, currentValue)
    }
  }, [__index, currentValue, itemValues, onItemValueChange, value])

  if (!isOpen) return null

  return (
    <ScrollView className={classNames('ct-dropdown-item', className)} scrollY>
      {options.map((option) => {
        const isSelected = option.value === currentValue

        return (
          <View
            key={option.value}
            className={classNames('ct-dropdown-item__option', {
              'ct-dropdown-item__option--selected': isSelected,
              'ct-dropdown-item__option--disabled': option.disabled,
            })}
            onClick={() => handleSelect(option)}
          >
            {option.icon && (
              <View className="ct-dropdown-item__icon">{option.icon}</View>
            )}
            <Text
              className="ct-dropdown-item__text"
              style={isSelected ? { color: activeColor } : undefined}
            >
              {option.text}
            </Text>
            {isSelected && (
              <Icon
                name="check"
                size={32}
                color={activeColor}
                className="ct-dropdown-item__check"
              />
            )}
          </View>
        )
      })}
    </ScrollView>
  )
}

export const Dropdown = {
  Menu: DropdownMenu,
  Item: DropdownItem,
}

export default Dropdown
export type { DropdownMenuProps, DropdownItemProps, DropdownOption } from './types'
