import { FC } from 'react'
import { Image, Swiper, SwiperItem, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { ImagePreviewProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const ImagePreview: FC<ImagePreviewProps> = ({
  images,
  open,
  current,
  defaultCurrent = 0,
  showIndicator = true,
  closable = true,
  onChange,
  onClose,
  className,
}) => {
  /**
   * Hooks
   */
  const [currentIndex, setCurrentIndex] = useControllable({
    value: current,
    defaultValue: defaultCurrent,
    onChange,
  })

  /**
   * Early Returns
   */
  if (!open) return null

  return (
    <View className={classNames('ct-image-preview', className)}>
      <View className="ct-image-preview__mask" onClick={onClose} />

      {closable && (
        <View className="ct-image-preview__close" onClick={onClose}>
          <Icon name="close" size={48} color="#fff" />
        </View>
      )}

      <Swiper
        className="ct-image-preview__swiper"
        current={currentIndex}
        onChange={(event) => setCurrentIndex(event.detail.current)}
      >
        {images.map((src, index) => (
          <SwiperItem key={index} className="ct-image-preview__item">
            <Image
              src={src}
              mode="aspectFit"
              className="ct-image-preview__image"
            />
          </SwiperItem>
        ))}
      </Swiper>

      {showIndicator && (
        <View className="ct-image-preview__indicator">
          <Text>
            {currentIndex + 1} / {images.length}
          </Text>
        </View>
      )}
    </View>
  )
}

export default ImagePreview
export type { ImagePreviewProps } from './types'
