import {
  cloneElement,
  createContext,
  FC,
  isValidElement,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { Form as TaroForm, Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { FormItemProps, FormProps, FormRule } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface FormContextValue {
  layout: 'horizontal' | 'vertical'
  labelWidth?: string | number
  values: Record<string, any>
  errors: Record<string, string | undefined>
  setFieldValue: (name: string, value: any) => void
  registerField: (name: string, rules?: FormRule[]) => void
  unregisterField: (name: string) => void
}

type FormComponent = FC<FormProps> & {
  Item: FC<FormItemProps>
}

/**
 * Context
 */
const FormContext = createContext<FormContextValue | null>(null)

export const Form: FormComponent = ({
  values,
  layout = 'horizontal',
  labelWidth,
  initialValues,
  onValuesChange,
  onSubmit,
  onFinishFailed,
  children,
  className,
}) => {
  /**
   * States
   */
  const [innerValues, setInnerValues] = useState<Record<string, any>>(
    initialValues ?? {},
  )
  const [errors, setErrors] = useState<Record<string, string | undefined>>({})
  const rulesRef = useRef<Record<string, FormRule[]>>({})

  /**
   * Derived Values
   */
  const isControlled = values !== undefined

  const currentValues = useMemo(
    () => (isControlled ? values ?? {} : innerValues),
    [innerValues, isControlled, values],
  )

  /**
   * Effects
   */
  useEffect(() => {
    if (!isControlled && initialValues) {
      setInnerValues(initialValues)
    }
  }, [initialValues, isControlled])

  /**
   * Callbacks
   */
  const registerField = (name: string, rules?: FormRule[]) => {
    rulesRef.current[name] = rules ?? []
  }

  const unregisterField = (name: string) => {
    delete rulesRef.current[name]
  }

  const setFieldValue = (name: string, value: any) => {
    const nextValues = { ...currentValues, [name]: value }
    if (!isControlled) {
      setInnerValues(nextValues)
    }
    setErrors((prev) => ({ ...prev, [name]: undefined }))
    onValuesChange?.({ [name]: value }, nextValues)
  }

  const validateField = async (
    name: string,
    value: any,
    rules: FormRule[]
  ) => {
    for (const rule of rules) {
      if (rule.required) {
        const empty =
          value === undefined ||
          value === null ||
          value === '' ||
          (Array.isArray(value) && value.length === 0)
        if (empty) {
          return rule.message ?? `${name}不能为空`
        }
      }
      if (rule.pattern && value !== undefined && value !== null && value !== '') {
        if (!rule.pattern.test(String(value))) {
          return rule.message ?? `${name}格式不正确`
        }
      }
      if (rule.min !== undefined) {
        const length = typeof value === 'number' ? value : String(value ?? '').length
        if (length < rule.min) {
          return rule.message ?? `${name}不能少于${rule.min}`
        }
      }
      if (rule.max !== undefined) {
        const length = typeof value === 'number' ? value : String(value ?? '').length
        if (length > rule.max) {
          return rule.message ?? `${name}不能超过${rule.max}`
        }
      }
      if (rule.validator) {
        const result = await rule.validator(value)
        if (!result) {
          return rule.message ?? `${name}校验失败`
        }
      }
    }
    return undefined
  }

  const validateAll = async () => {
    const entries = Object.entries(rulesRef.current)
    const errorList: { name: string; message: string }[] = []

    for (const [name, rules] of entries) {
      const message = await validateField(name, currentValues[name], rules)
      if (message) {
        errorList.push({ name, message })
      }
    }

    if (errorList.length) {
      const nextErrors = errorList.reduce<Record<string, string>>((acc, item) => {
        acc[item.name] = item.message
        return acc
      }, {})
      setErrors(nextErrors)
      onFinishFailed?.(errorList)
      return false
    }

    setErrors({})
    return true
  }

  const handleSubmit = async () => {
    const valid = await validateAll()
    if (valid) {
      onSubmit?.(currentValues)
    }
  }

  return (
    <FormContext.Provider
      value={{
        layout,
        labelWidth,
        values: currentValues,
        errors,
        setFieldValue,
        registerField,
        unregisterField,
      }}
    >
      <TaroForm
        className={classNames('ct-form', `ct-form--${layout}`, className)}
        onSubmit={handleSubmit}
      >
        {children}
      </TaroForm>
    </FormContext.Provider>
  )
}

export const FormItem: FC<FormItemProps> = ({
  label,
  required,
  name,
  rules,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const context = useContext(FormContext)

  /**
   * Derived Values
   */
  const mergedRules = useMemo<FormRule[]>(() => {
    const nextRules = rules ? [...rules] : []
    if (required && !nextRules.some((rule) => rule.required)) {
      nextRules.unshift({ required: true })
    }
    return nextRules
  }, [required, rules])

  const fieldValue = context?.values?.[name]
  const fieldError = context?.errors?.[name]

  const labelStyle =
    context?.labelWidth !== undefined
      ? {
          width:
            typeof context.labelWidth === 'number'
              ? `${context.labelWidth}px`
              : context.labelWidth,
        }
      : undefined

  /**
   * Effects
   */
  useEffect(() => {
    if (!context) return undefined
    context.registerField(name, mergedRules)
    return () => context.unregisterField(name)
  }, [context, mergedRules, name])

  /**
   * Render Helpers
   */
  const renderChildren = () => {
    if (!context || !isValidElement(children)) return children

    const valuePropName =
      children.props.checked !== undefined ||
      children.props.defaultChecked !== undefined ||
      typeof fieldValue === 'boolean'
        ? 'checked'
        : 'value'

    const handleChange = (...args: any[]) => {
      const nextValue = args[0]?.detail?.value ?? args[0]
      context.setFieldValue(name, nextValue)
      children.props.onChange?.(...args)
    }

    return cloneElement(children, {
      [valuePropName]: fieldValue,
      onChange: handleChange,
    })
  }

  return (
    <View className={classNames('ct-form-item', className)}>
      {label && (
        <View className="ct-form-item__label" style={labelStyle}>
          {required && <Text className="ct-form-item__required">*</Text>}
          <Text>{label}</Text>
        </View>
      )}
      <View className="ct-form-item__content">{renderChildren()}</View>
      {fieldError && (
        <View className="ct-form-item__error">
          <Text>{fieldError}</Text>
        </View>
      )}
    </View>
  )
}

Form.Item = FormItem

export default Form
export type { FormProps, FormItemProps, FormRule } from './types'
