import { FC, useEffect, useMemo, useState } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Button } from '../button'
import { Icon } from '../icon'

/**
 * Types
 */
import type { CalendarProps, CalendarType } from './types'

import './index.scss'

/**
 * Internal Types
 */
type CalendarValue = Date | Date[] | [Date, Date] | undefined

/**
 * Constants
 */
const dayLabels = ['日', '一', '二', '三', '四', '五', '六']

/**
 * Helpers
 */
const toDayNumber = (date: Date) =>
  date.getFullYear() * 10000 + (date.getMonth() + 1) * 100 + date.getDate()

const isSameDay = (a: Date, b: Date) => toDayNumber(a) === toDayNumber(b)

const getBaseDate = (value: CalendarValue, type: CalendarType) => {
  if (value instanceof Date) return value
  if (Array.isArray(value) && value.length > 0) return value[0]
  if (type === 'single') return new Date()
  return new Date()
}

const normalizeRange = (value: CalendarValue) => {
  if (Array.isArray(value)) {
    return {
      start: value[0],
      end: value[1],
    }
  }
  if (value instanceof Date) {
    return { start: value, end: undefined }
  }
  return { start: undefined, end: undefined }
}

/**
 * Main Component
 */
export const Calendar: FC<CalendarProps> = ({
  type = 'single',
  value,
  defaultValue,
  minDate,
  maxDate,
  open,
  visible,
  showMask = true,
  closeOnOverlayClick = true,
  title = '选择日期',
  confirmText = '确定',
  showConfirm = true,
  firstDayOfWeek = 0,
  onChange,
  onConfirm,
  onClose,
  className,
}) => {
  /**
   * Derived Values
   */
  const resolvedOpen = open ?? visible ?? false

  /**
   * Hooks
   */
  const [selectedValue, setSelectedValue] = useControllable<CalendarValue>({
    value,
    defaultValue:
      defaultValue ?? (type === 'single' ? undefined : ([] as Date[])),
    onChange,
  })

  /**
   * States
   */
  const [selectingRangeEnd, setSelectingRangeEnd] = useState(false)
  const [viewDate, setViewDate] = useState(() => getBaseDate(selectedValue, type))

  /**
   * Derived Values
   */
  const baseDate = useMemo(
    () => getBaseDate(selectedValue, type),
    [selectedValue, type]
  )
  const year = viewDate.getFullYear()
  const month = viewDate.getMonth()

  const weekLabels = useMemo(() => {
    const start = Math.max(0, Math.min(6, firstDayOfWeek))
    return [...dayLabels.slice(start), ...dayLabels.slice(0, start)]
  }, [firstDayOfWeek])

  const monthCells = useMemo(() => {
    const firstDay = new Date(year, month, 1).getDay()
    const daysInMonth = new Date(year, month + 1, 0).getDate()
    const offset = (firstDay - firstDayOfWeek + 7) % 7
    const total = Math.ceil((offset + daysInMonth) / 7) * 7

    return Array.from({ length: total }).map((_, index) => {
      const day = index - offset + 1
      if (day <= 0 || day > daysInMonth) return null
      return new Date(year, month, day)
    })
  }, [firstDayOfWeek, month, year])

  const toMonthNumber = (date: Date) => date.getFullYear() * 12 + date.getMonth()
  const minMonth = minDate ? toMonthNumber(minDate) : undefined
  const maxMonth = maxDate ? toMonthNumber(maxDate) : undefined
  const canGoPrev = minMonth === undefined || toMonthNumber(viewDate) > minMonth
  const canGoNext = maxMonth === undefined || toMonthNumber(viewDate) < maxMonth

  const selectedSingle = selectedValue instanceof Date ? selectedValue : undefined
  const selectedMultiple = Array.isArray(selectedValue)
    ? (selectedValue as Date[])
    : []
  const { start: rangeStart, end: rangeEnd } = normalizeRange(selectedValue)

  /**
   * Callbacks
   */
  const handlePrevMonth = () => {
    if (!canGoPrev) return
    setViewDate(new Date(year, month - 1, 1))
  }

  const handleNextMonth = () => {
    if (!canGoNext) return
    setViewDate(new Date(year, month + 1, 1))
  }

  const isDisabled = (date: Date) => {
    const dayValue = toDayNumber(date)
    if (minDate && dayValue < toDayNumber(minDate)) return true
    if (maxDate && dayValue > toDayNumber(maxDate)) return true
    return false
  }

  const handleSelect = (date: Date) => {
    if (isDisabled(date)) return

    if (type === 'single') {
      setSelectedValue(date)
      return
    }

    if (type === 'multiple') {
      const current = Array.isArray(selectedValue)
        ? (selectedValue as Date[])
        : []
      const exists = current.some((item) => isSameDay(item, date))
      const next = exists
        ? current.filter((item) => !isSameDay(item, date))
        : [...current, date]
      setSelectedValue(next)
      return
    }

    const { start, end } = normalizeRange(selectedValue)
    if (!start || (end && !selectingRangeEnd)) {
      setSelectedValue([date, date])
      setSelectingRangeEnd(true)
      return
    }

    const [rangeStartNew, rangeEndNew] =
      toDayNumber(date) < toDayNumber(start) ? [date, start] : [start, date]
    setSelectedValue([rangeStartNew, rangeEndNew])
    setSelectingRangeEnd(false)
  }

  const handleConfirm = () => {
    if (!onConfirm) return
    if (type === 'single') {
      onConfirm(selectedValue as Date)
      return
    }
    if (type === 'multiple') {
      onConfirm((selectedValue as Date[]) || [])
      return
    }
    const { start, end } = normalizeRange(selectedValue)
    if (start && end) {
      onConfirm([start, end])
    } else if (start) {
      onConfirm([start, start])
    }
  }

  const handleOverlayClick = () => {
    if (!closeOnOverlayClick) return
    onClose?.()
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (type !== 'range') return
    const { start, end } = normalizeRange(selectedValue)
    if (!start) {
      setSelectingRangeEnd(false)
      return
    }
    if (end && !isSameDay(start, end)) {
      setSelectingRangeEnd(false)
    }
  }, [selectedValue, type])

  useEffect(() => {
    if (resolvedOpen) {
      setViewDate(baseDate)
    }
  }, [baseDate, resolvedOpen])

  /**
   * Early Returns
   */
  if (!resolvedOpen) return null

  return (
    <View className="ct-calendar__wrapper">
      {showMask && <View className="ct-calendar__mask" onClick={handleOverlayClick} />}
      <View className={classNames('ct-calendar', className)}>
        <View className="ct-calendar__header">
          <Text className="ct-calendar__title">{title}</Text>
          {onClose && (
            <View
              className="ct-calendar__close"
              hoverClass="ct-clickable--hover"
              onClick={onClose}
            >
              <Icon name="close" size={28} />
            </View>
          )}
        </View>

        <View className="ct-calendar__month">
          <View
            className={classNames('ct-calendar__nav', {
              'ct-calendar__nav--disabled': !canGoPrev,
            })}
            hoverClass={canGoPrev ? 'ct-clickable--hover' : 'none'}
            onClick={handlePrevMonth}
          >
            <Icon name="arrow-left" size={28} />
          </View>
          <Text>{`${year}年${month + 1}月`}</Text>
          <View
            className={classNames('ct-calendar__nav', {
              'ct-calendar__nav--disabled': !canGoNext,
            })}
            hoverClass={canGoNext ? 'ct-clickable--hover' : 'none'}
            onClick={handleNextMonth}
          >
            <Icon name="arrow-right" size={28} />
          </View>
        </View>

      <View className="ct-calendar__week">
        {weekLabels.map((label) => (
          <View key={label} className="ct-calendar__week-item">
            <Text>{label}</Text>
          </View>
        ))}
      </View>

      <View className="ct-calendar__grid">
        {monthCells.map((date, index) => {
          if (!date) {
            return <View key={`empty-${index}`} className="ct-calendar__cell" />
          }

          const disabled = isDisabled(date)
          const selected =
            type === 'single'
              ? selectedSingle && isSameDay(selectedSingle, date)
              : type === 'multiple'
                ? selectedMultiple.some((item) => isSameDay(item, date))
                : rangeStart && isSameDay(rangeStart, date) ||
                  rangeEnd && isSameDay(rangeEnd, date)

          const inRange =
            type === 'range' && rangeStart && rangeEnd
              ? toDayNumber(date) >= toDayNumber(rangeStart) &&
                toDayNumber(date) <= toDayNumber(rangeEnd)
              : false

          const isStart =
            type === 'range' && rangeStart && isSameDay(rangeStart, date)
          const isEnd =
            type === 'range' && rangeEnd && isSameDay(rangeEnd, date)

          return (
            <View
              key={date.toISOString()}
              className={classNames('ct-calendar__cell', {
                'ct-calendar__cell--disabled': disabled,
                'ct-calendar__cell--selected': selected,
                'ct-calendar__cell--in-range': inRange,
                'ct-calendar__cell--start': isStart,
                'ct-calendar__cell--end': isEnd,
              })}
              hoverClass={disabled ? 'none' : 'ct-clickable--hover'}
              onClick={() => handleSelect(date)}
            >
              <Text>{date.getDate()}</Text>
            </View>
          )
        })}
      </View>

      {showConfirm && (
        <View className="ct-calendar__footer">
          <Button variant="primary" onClick={handleConfirm}>
            {confirmText}
          </Button>
        </View>
      )}
    </View>
    </View>
  )
}

export default Calendar
export type { CalendarProps, CalendarType } from './types'
