import { FC, useCallback, useMemo } from 'react'
import { Input, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { StepperProps } from './types'

import './index.scss'

/**
 * Constants
 */
const sizeMap = {
  small: 56,
  medium: 64,
  large: 80,
}

export const Stepper: FC<StepperProps> = ({
  value: propValue,
  defaultValue = 1,
  min = 0,
  max = Infinity,
  step = 1,
  disabled = false,
  inputWidth,
  size = 'medium',
  disableInput = false,
  digits = 0,
  onChange,
  onOverflow,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable<number>({
    value: propValue,
    defaultValue,
    onChange,
  })

  /**
   * Render Helpers
   */
  const formatValue = useCallback(
    (val: number) => {
      let result = Math.max(min, Math.min(max, val))
      if (digits > 0) {
        result = Number(result.toFixed(digits))
      } else {
        result = Math.round(result)
      }
      return result
    },
    [min, max, digits]
  )

  /**
   * Derived Values
   */
  const isMinDisabled = useMemo(() => value <= min, [value, min])
  const isMaxDisabled = useMemo(() => value >= max, [value, max])
  const buttonSize = sizeMap[size]
  const inputWidthValue = inputWidth ?? (size === 'small' ? 80 : size === 'large' ? 120 : 100)

  /**
   * Callbacks
   */
  const handleMinus = () => {
    if (disabled || isMinDisabled) {
      if (isMinDisabled) onOverflow?.('min')
      return
    }
    const newValue = formatValue(value - step)
    setValue(newValue)
  }

  const handlePlus = () => {
    if (disabled || isMaxDisabled) {
      if (isMaxDisabled) onOverflow?.('max')
      return
    }
    const newValue = formatValue(value + step)
    setValue(newValue)
  }

  const handleInputChange = (e: any) => {
    const inputValue = e.detail.value
    if (inputValue === '' || inputValue === '-') return

    const numValue = Number(inputValue)
    if (isNaN(numValue)) return

    const newValue = formatValue(numValue)
    setValue(newValue)
  }

  const handleInputBlur = () => {
    const formattedValue = formatValue(value)
    if (formattedValue !== value) {
      setValue(formattedValue)
    }
  }

  return (
    <View
      className={classNames(
        'ct-stepper',
        `ct-stepper--${size}`,
        {
          'ct-stepper--disabled': disabled,
        },
        className
      )}
    >
      <View
        className={classNames('ct-stepper__button ct-stepper__minus', {
          'ct-stepper__button--disabled': isMinDisabled || disabled,
        })}
        style={{ width: `${buttonSize}rpx`, height: `${buttonSize}rpx` }}
        onClick={handleMinus}
      >
        <Icon name="minus" size={size === 'small' ? 28 : 32} />
      </View>

      <Input
        className="ct-stepper__input"
        type="digit"
        value={String(digits > 0 ? value.toFixed(digits) : value)}
        disabled={disabled || disableInput}
        style={{
          width: typeof inputWidthValue === 'number' ? `${inputWidthValue}rpx` : inputWidthValue,
          height: `${buttonSize}rpx`,
        }}
        onInput={handleInputChange}
        onBlur={handleInputBlur}
      />

      <View
        className={classNames('ct-stepper__button ct-stepper__plus', {
          'ct-stepper__button--disabled': isMaxDisabled || disabled,
        })}
        style={{ width: `${buttonSize}rpx`, height: `${buttonSize}rpx` }}
        onClick={handlePlus}
      >
        <Icon name="plus" size={size === 'small' ? 28 : 32} />
      </View>
    </View>
  )
}

export default Stepper
export type { StepperProps } from './types'
