import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { TagProps } from './types'

import './index.scss'

/**
 * Helpers
 */
const toRgba = (color: string, alpha: number) => {
  if (color.startsWith('#')) {
    const hex = color.replace('#', '')
    const normalized =
      hex.length === 3
        ? hex
            .split('')
            .map((c) => c + c)
            .join('')
        : hex
    if (normalized.length !== 6) return color
    const r = parseInt(normalized.slice(0, 2), 16)
    const g = parseInt(normalized.slice(2, 4), 16)
    const b = parseInt(normalized.slice(4, 6), 16)
    return `rgba(${r}, ${g}, ${b}, ${alpha})`
  }

  const match = color.match(/rgba?\(([^)]+)\)/)
  if (match) {
    const parts = match[1].split(',').map((val) => val.trim())
    if (parts.length >= 3) {
      const [r, g, b] = parts
      return `rgba(${r}, ${g}, ${b}, ${alpha})`
    }
  }

  return color
}

export const Tag: FC<TagProps> = ({
  variant = 'filled',
  size = 'md',
  color = 'primary',
  customColor,
  round = false,
  closable = false,
  onClose,
  onClick,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const isClickable = !!onClick
  const tagStyle = customColor
    ? {
        backgroundColor:
          variant === 'filled'
            ? customColor
            : variant === 'light'
              ? toRgba(customColor, 0.12)
              : 'transparent',
        borderColor: customColor,
        color: variant === 'filled' ? '#fff' : customColor,
      }
    : undefined

  /**
   * Callbacks
   */
  const handleClose = (e: any) => {
    e.stopPropagation()
    onClose?.()
  }

  return (
    <View
      className={classNames(
        'ct-tag',
        `ct-tag--${variant}`,
        `ct-tag--${size}`,
        `ct-tag--${color}`,
        { 'ct-tag--round': round, 'ct-tag--clickable': isClickable },
        className
      )}
      style={tagStyle}
      hoverClass={isClickable ? 'ct-clickable--hover' : 'none'}
      onClick={onClick}
    >
      <Text className="ct-tag__text">{children}</Text>
      {closable && (
        <View className="ct-tag__close" onClick={handleClose}>
          <Icon name="close" size={20} />
        </View>
      )}
    </View>
  )
}

export default Tag
export type { TagProps, TagVariant, TagSize, TagColor } from './types'
