import { FC, useMemo, useState } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'
import { Picker } from '../picker'

/**
 * Types
 */
import type { SelectOption, SelectProps } from './types'

import './index.scss'

export const Select: FC<SelectProps> = ({
  value: propValue,
  defaultValue,
  options,
  placeholder = '请选择',
  disabled = false,
  title = '请选择',
  confirmText,
  cancelText,
  clearable = false,
  onChange,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable<string | number | undefined>({
    value: propValue,
    defaultValue,
    onChange: (val) => {
      const option = options.find((opt) => opt.value === val)
      onChange?.(val, option)
    },
  })

  /**
   * States
   */
  const [open, setOpen] = useState(false)

  /**
   * Derived Values
   */
  const selectedOption = useMemo(
    () => options.find((opt) => opt.value === value),
    [options, value]
  )

  const pickerOptions = useMemo(
    () =>
      options.map((opt) => ({
        label: opt.label,
        value: opt.value,
        disabled: opt.disabled,
      })),
    [options]
  )

  /**
   * Callbacks
   */
  const handleTriggerClick = () => {
    if (disabled) return
    setOpen(true)
  }

  const handleClear = (e: any) => {
    e.stopPropagation()
    setValue(undefined)
  }

  const handleConfirm = (val: (string | number)[]) => {
    setValue(val[0])
    setOpen(false)
  }

  const handleClose = () => {
    setOpen(false)
  }

  return (
    <View className={classNames('ct-select', { 'ct-select--disabled': disabled }, className)}>
      <View className="ct-select__trigger" onClick={handleTriggerClick}>
        <Text
          className={classNames('ct-select__value', {
            'ct-select__value--placeholder': !selectedOption,
          })}
        >
          {selectedOption?.label || placeholder}
        </Text>

        {clearable && selectedOption && !disabled && (
          <View className="ct-select__clear" onClick={handleClear}>
            <Icon
              name="close-circle-fill"
              size={32}
              color="var(--ct-color-text-quaternary)"
            />
          </View>
        )}

        <View className="ct-select__arrow">
          <Icon name="arrow-down" size={32} color="var(--ct-color-text-tertiary)" />
        </View>
      </View>

      <Picker
        open={open}
        title={title}
        confirmText={confirmText}
        cancelText={cancelText}
        options={pickerOptions}
        value={value !== undefined ? [value] : undefined}
        onConfirm={handleConfirm}
        onClose={handleClose}
      />
    </View>
  )
}

export default Select
export type { SelectProps, SelectOption } from './types'
