import { FC } from 'react'
import { Image, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { iconPaths } from './paths'

/**
 * Types
 */
import type { IconProps } from './types'

import './index.scss'

/**
 * Helpers
 */
const toBase64 = (str: string): string => {
  if (typeof btoa === 'function') {
    return btoa(str)
  }
  // 小程序环境使用 ArrayBuffer 转换
  const encoder = new TextEncoder()
  const bytes = encoder.encode(str)
  const base64Chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  let result = ''
  const len = bytes.length
  for (let i = 0; i < len; i += 3) {
    const a = bytes[i]
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    result += base64Chars[a >> 2]
    result += base64Chars[((a & 3) << 4) | (b >> 4)]
    result += i + 1 < len ? base64Chars[((b & 15) << 2) | (c >> 6)] : '='
    result += i + 2 < len ? base64Chars[c & 63] : '='
  }
  return result
}

export const Icon: FC<IconProps> = ({
  name,
  size = 40,
  color,
  renderMode = 'auto',
  onClick,
  className,
}) => {
  /**
   * Derived Values
   */
  const path = iconPaths[name]
  const env = Taro.getEnv?.()
  const useInlineSvg =
    renderMode === 'svg' || (renderMode === 'auto' && env === Taro.ENV_TYPE?.WEB)
  const isCssVar = typeof color === 'string' && color.startsWith('var(')
  const svgFill = useInlineSvg
    ? color ?? 'currentColor'
    : isCssVar
      ? '#1f2937'
      : color ?? '#1f2937'
  const svgMarkup = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><path fill="${svgFill}" fill-rule="evenodd" d="${path}"/></svg>`
  const svgBase64 = `data:image/svg+xml;base64,${toBase64(svgMarkup)}`

  /**
   * Early Returns
   */
  if (!path) return null

  return (
    <View
      className={classNames('ct-icon', className)}
      style={{ width: `${size}rpx`, height: `${size}rpx`, color }}
      onClick={onClick}
    >
      {useInlineSvg ? (
        <svg viewBox="0 0 1024 1024" fill="currentColor">
          <path d={path} fillRule="evenodd" />
        </svg>
      ) : (
        <Image src={svgBase64} mode="aspectFit" style={{ width: '100%', height: '100%' }} />
      )}
    </View>
  )
}

export default Icon
export type { IconProps, IconName } from './types'
