import { FC } from 'react'
import { Image, Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { EmptyProps, EmptyImageType } from './types'

import './index.scss'

/**
 * Constants
 */
const PLACEHOLDER_TEXT: Record<EmptyImageType, string> = {
  default: '暂无',
  error: '出错',
  network: '网络',
  search: '搜索',
  cart: '购物车',
  message: '消息',
  favorite: '收藏',
  order: '订单',
  comment: '评论',
}

export const Empty: FC<EmptyProps> = ({
  image,
  imageType = 'default',
  imageSize = 256,
  description = '暂无数据',
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const placeholderText = PLACEHOLDER_TEXT[imageType]

  return (
    <View className={classNames('ct-empty', className)}>
      {image ? (
        <Image
          className="ct-empty__image"
          src={image}
          mode="aspectFit"
          style={{ width: `${imageSize}rpx`, height: `${imageSize}rpx` }}
        />
      ) : (
        <View
          className={classNames(
            'ct-empty__placeholder',
            `ct-empty__placeholder--${imageType}`
          )}
          style={{ width: `${imageSize}rpx`, height: `${imageSize}rpx` }}
        >
          <Text className="ct-empty__placeholder-text">{placeholderText}</Text>
        </View>
      )}

      {description && (
        <View className="ct-empty__description">
          {typeof description === 'string' ? <Text>{description}</Text> : description}
        </View>
      )}

      {children && <View className="ct-empty__actions">{children}</View>}
    </View>
  )
}

export default Empty
export type { EmptyProps, EmptyImageType } from './types'
