import { FC, createContext, useContext } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { CheckboxGroupProps, CheckboxProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface CheckboxContextValue {
  value?: (string | number)[]
  disabled?: boolean
  onChange?: (val: string | number, checked: boolean) => void
}

type CheckboxComponent = FC<CheckboxProps> & {
  Group: FC<CheckboxGroupProps>
}

/**
 * Context
 */
const CheckboxContext = createContext<CheckboxContextValue>({})

export const Checkbox: CheckboxComponent = ({
  checked: propChecked,
  defaultChecked = false,
  disabled = false,
  indeterminate = false,
  value,
  onChange,
  shape = 'square',
  iconPosition = 'left',
  checkedColor,
  className,
  children,
}) => {
  /**
   * Hooks
   */
  const ctx = useContext(CheckboxContext)

  /**
   * Derived Values
   */
  const isGroupMode = ctx.value !== undefined
  const isChecked = isGroupMode
    ? value !== undefined && ctx.value?.includes(value)
    : propChecked

  const [checked, setChecked] = useControllable({
    value: isGroupMode ? isChecked : propChecked,
    defaultValue: defaultChecked,
    onChange,
  })
  const isDisabled = disabled || ctx.disabled
  const iconStyle =
    checkedColor && checked
      ? { backgroundColor: checkedColor, borderColor: checkedColor }
      : undefined

  /**
   * Callbacks
   */
  const handleClick = () => {
    if (isDisabled) return

    if (isGroupMode) {
      if (value === undefined) {
        if (process.env.NODE_ENV !== 'production') {
          console.warn('[Checkbox] value is required when used inside Checkbox.Group.')
        }
        return
      }
      ctx.onChange?.(value, !checked)
    } else {
      setChecked(!checked)
    }
  }

  return (
    <View
      className={classNames(
        'ct-checkbox',
        `ct-checkbox--${shape}`,
        {
          'ct-checkbox--checked': checked,
          'ct-checkbox--disabled': isDisabled,
          'ct-checkbox--indeterminate': indeterminate,
          'ct-checkbox--right': iconPosition === 'right',
        },
        className
      )}
      hoverClass={isDisabled ? 'none' : 'ct-clickable--hover'}
      onClick={handleClick}
    >
      <View className="ct-checkbox__icon" style={iconStyle}>
        {checked && !indeterminate && <Icon name="check" size={28} color="#fff" />}
        {indeterminate && <View className="ct-checkbox__indeterminate" />}
      </View>
      {children && (
        <View className="ct-checkbox__label">
          {typeof children === 'string' ? <Text>{children}</Text> : children}
        </View>
      )}
    </View>
  )
}

export const CheckboxGroup: FC<CheckboxGroupProps> = ({
  value: propValue,
  defaultValue = [],
  disabled = false,
  max,
  direction = 'vertical',
  onChange,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable({
    value: propValue,
    defaultValue,
    onChange,
  })

  /**
   * Callbacks
   */
  const handleChange = (val: string | number, checked: boolean) => {
    let newValue: (string | number)[]

    if (checked) {
      if (max && value.length >= max) return
      newValue = [...value, val]
    } else {
      newValue = value.filter((v) => v !== val)
    }

    setValue(newValue)
  }

  return (
    <CheckboxContext.Provider value={{ value, disabled, onChange: handleChange }}>
      <View
        className={classNames(
          'ct-checkbox-group',
          `ct-checkbox-group--${direction}`,
          className
        )}
      >
        {children}
      </View>
    </CheckboxContext.Provider>
  )
}

Checkbox.Group = CheckboxGroup

export default Checkbox
export type { CheckboxProps, CheckboxGroupProps } from './types'
