import {
  Children,
  FC,
  cloneElement,
  isValidElement,
  useEffect,
  useState,
} from 'react'
import { Image, Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { AvatarGroupProps, AvatarProps } from './types'

import './index.scss'

/**
 * Constants
 */
const SIZE_MAP = { xs: 48, sm: 64, md: 80, lg: 96, xl: 128 }

/**
 * Internal Types
 */
type AvatarComponent = FC<AvatarProps> & {
  Group: FC<AvatarGroupProps>
}

export const Avatar: AvatarComponent = ({
  src,
  fallback,
  size = 'md',
  shape = 'circle',
  alt,
  backgroundColor,
  color,
  onClick,
  children,
  className,
}) => {
  /**
   * States
   */
  const [error, setError] = useState(false)
  const [currentSrc, setCurrentSrc] = useState(src || fallback)

  /**
   * Derived Values
   */
  const sizeValue = typeof size === 'number' ? size : SIZE_MAP[size]
  const style = {
    width: `${sizeValue}rpx`,
    height: `${sizeValue}rpx`,
    backgroundColor,
    color,
  }
  const imageSrc = currentSrc
  const displayText = alt?.charAt(0)?.toUpperCase()

  /**
   * Callbacks
   */
  const handleError = () => {
    if (currentSrc && currentSrc !== fallback && fallback) {
      setCurrentSrc(fallback)
      setError(false)
      return
    }
    setError(true)
  }

  /**
   * Effects
   */
  useEffect(() => {
    setCurrentSrc(src || fallback)
    setError(false)
  }, [fallback, src])

  return (
    <View
      className={classNames('ct-avatar', `ct-avatar--${shape}`, className)}
      style={style}
      onClick={onClick}
    >
      {imageSrc && !error ? (
        <Image
          src={imageSrc}
          className="ct-avatar__image"
          mode="aspectFill"
          onError={handleError}
        />
      ) : children ? (
        <View className="ct-avatar__content">{children}</View>
      ) : displayText ? (
        <Text
          className="ct-avatar__text"
          style={{ fontSize: `${sizeValue * 0.4}rpx` }}
        >
          {displayText}
        </Text>
      ) : null}
    </View>
  )
}

export const AvatarGroup: FC<AvatarGroupProps> = ({
  max = 5,
  size = 'md',
  gap = -16,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const avatars = Children.toArray(children).filter(isValidElement)
  const visibleAvatars = max ? avatars.slice(0, max) : avatars
  const remainingCount = avatars.length - visibleAvatars.length

  return (
    <View className={classNames('ct-avatar-group', className)}>
      {visibleAvatars.map((child, index) => (
        <View
          key={index}
          className="ct-avatar-group__item"
          style={{ marginLeft: index === 0 ? 0 : `${gap}rpx` }}
        >
          {cloneElement(child as React.ReactElement, { size })}
        </View>
      ))}

      {remainingCount > 0 && (
        <View
          className="ct-avatar-group__item"
          style={{ marginLeft: `${gap}rpx` }}
        >
          <Avatar size={size} backgroundColor="var(--ct-color-fill-secondary)">
            <Text>+{remainingCount}</Text>
          </Avatar>
        </View>
      )}
    </View>
  )
}

Avatar.Group = AvatarGroup

export default Avatar
export type { AvatarProps, AvatarGroupProps, AvatarSize, AvatarShape } from './types'
