import { FC, useEffect, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { TooltipProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const Tooltip: FC<TooltipProps> = ({
  content,
  open,
  defaultOpen = false,
  onOpenChange,
  placement = 'top',
  trigger = 'click',
  children,
  theme = 'dark',
  showDelay = 0,
  className,
}) => {
  /**
   * Hooks
   */
  const [isOpen, setIsOpen] = useControllable({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })

  /**
   * States
   */
  const [position, setPosition] = useState({ top: 0, left: 0 })

  /**
   * Refs
   */
  const triggerRef = useRef<string>(`tooltip-${Date.now()}`)
  const timerRef = useRef<ReturnType<typeof setTimeout>>()

  /**
   * Callbacks
   */
  const calculatePosition = () => {
    const query = Taro.createSelectorQuery()
    query.select(`#${triggerRef.current}`).boundingClientRect()
    query.selectViewport().scrollOffset()
    query.exec((res) => {
      if (!res[0]) return

      const rect = res[0]
      const scrollTop = res[1]?.scrollTop || 0

      let top = 0
      let left = rect.left + rect.width / 2

      switch (placement) {
        case 'top':
        case 'top-start':
        case 'top-end':
          top = rect.top + scrollTop - 16
          break
        case 'bottom':
        case 'bottom-start':
        case 'bottom-end':
          top = rect.bottom + scrollTop + 16
          break
        case 'left':
          top = rect.top + scrollTop + rect.height / 2
          left = rect.left - 16
          break
        case 'right':
          top = rect.top + scrollTop + rect.height / 2
          left = rect.right + 16
          break
      }

      if (placement === 'top-start' || placement === 'bottom-start') {
        left = rect.left
      } else if (placement === 'top-end' || placement === 'bottom-end') {
        left = rect.right
      }

      setPosition({ top, left })
    })
  }

  const handleClick = () => {
    if (trigger !== 'click') return
    if (timerRef.current) clearTimeout(timerRef.current)

    if (!isOpen && showDelay > 0) {
      timerRef.current = setTimeout(() => setIsOpen(true), showDelay)
    } else {
      setIsOpen(!isOpen)
    }
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (isOpen) {
      calculatePosition()
    }
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [isOpen])

  return (
    <View className={classNames('ct-tooltip', className)}>
      <View
        id={triggerRef.current}
        className="ct-tooltip__trigger"
        onClick={handleClick}
      >
        {children}
      </View>

      {isOpen && (
        <View
          className={classNames(
            'ct-tooltip__content',
            `ct-tooltip__content--${placement}`,
            `ct-tooltip__content--${theme}`,
          )}
          style={{
            top: `${position.top}px`,
            left: `${position.left}px`,
          }}
          onClick={() => setIsOpen(false)}
        >
          <View className="ct-tooltip__arrow" />
          <Text className="ct-tooltip__text">{content}</Text>
        </View>
      )}
    </View>
  )
}

export default Tooltip
export type { TooltipPlacement, TooltipProps } from './types'
