import { cloneElement, FC, isValidElement, ReactElement } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { ButtonProps } from './types'

import './index.scss'

/**
 * Helpers
 */
const getIconColor = (variant: string): string | undefined => {
  switch (variant) {
    case 'primary':
    case 'danger':
      return '#ffffff'
    case 'secondary':
    case 'link':
      return 'var(--ct-color-primary)'
    case 'outline':
    case 'ghost':
      return 'var(--ct-color-text-primary)'
    default:
      return undefined
  }
}

export const Button: FC<ButtonProps> = ({
  variant = 'primary',
  size = 'md',
  disabled = false,
  loading = false,
  block = false,
  icon,
  iconRight,
  onClick,
  className,
  style,
  children,
}) => {
  /**
   * Callbacks
   */
  const handleClick = () => {
    if (disabled || loading) return
    onClick?.()
  }

  /**
   * Render Helpers
   */
  const renderIcon = (iconElement: React.ReactNode) => {
    if (isValidElement(iconElement)) {
      const iconColor = getIconColor(variant)
      return cloneElement(iconElement as ReactElement<{ color?: string }>, {
        color: iconColor,
      })
    }
    return iconElement
  }

  return (
    <View
      className={classNames(
        'ct-button',
        `ct-button--${variant}`,
        `ct-button--${size}`,
        {
          'ct-button--block': block,
          'ct-button--disabled': disabled,
          'ct-button--loading': loading,
        },
        className
      )}
      style={style}
      onClick={handleClick}
      hoverClass={disabled || loading ? 'none' : 'ct-button--hover'}
      hoverStayTime={100}
    >
      {loading && (
        <View className="ct-button__loading">
          <View className="ct-button__spinner" />
        </View>
      )}
      {!loading && icon && (
        <View className="ct-button__icon ct-button__icon--left">{renderIcon(icon)}</View>
      )}
      <Text className="ct-button__text">{children}</Text>
      {!loading && iconRight && (
        <View className="ct-button__icon ct-button__icon--right">
          {renderIcon(iconRight)}
        </View>
      )}
    </View>
  )
}

export default Button
export type { ButtonProps, ButtonVariant, ButtonSize } from './types'
