import { FC, useEffect, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { OVERLAY_ANIMATION_DURATION } from '../../constants/animation'

/**
 * Types
 */
import type { ActionSheetAction, ActionSheetProps } from './types'

import './index.scss'

export const ActionSheet: FC<ActionSheetProps> = ({
  open,
  actions,
  title,
  description,
  cancelText = '取消',
  onAction,
  onCancel,
  onClose,
  closeOnOverlayClick = true,
}) => {
  /**
   * States
   */
  const [show, setShow] = useState(false)
  const [animating, setAnimating] = useState(false)

  /**
   * Callbacks
   */
  const handleOverlayClick = () => {
    if (closeOnOverlayClick) {
      onCancel?.()
      onClose?.()
    }
  }

  const handleActionClick = (action: ActionSheetAction, index: number) => {
    if (action.disabled) return
    onAction?.(action, index)
    onClose?.()
  }

  const handleCancel = () => {
    onCancel?.()
    onClose?.()
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (open) {
      setShow(true)
      Taro.nextTick(() => setAnimating(true))
    } else {
      setAnimating(false)
      const timer = setTimeout(() => setShow(false), OVERLAY_ANIMATION_DURATION)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [open])

  /**
   * Early Returns
   */
  if (!show) return null

  return (
    <View className="ct-action-sheet" catchMove>
      <View
        className={classNames('ct-action-sheet__mask', {
          'ct-action-sheet__mask--visible': animating,
        })}
        onClick={handleOverlayClick}
      />
      <View
        className={classNames('ct-action-sheet__panel', {
          'ct-action-sheet__panel--visible': animating,
        })}
      >
        {(title || description) && (
          <View className="ct-action-sheet__header">
            {title && <Text className="ct-action-sheet__title">{title}</Text>}
            {description && (
              <Text className="ct-action-sheet__description">{description}</Text>
            )}
          </View>
        )}

        <View className="ct-action-sheet__actions">
          {actions.map((action, index) => (
            <View
              key={action.value ?? index}
              className={classNames('ct-action-sheet__action', {
                'ct-action-sheet__action--danger': action.danger,
                'ct-action-sheet__action--disabled': action.disabled,
              })}
              style={action.color ? { color: action.color } : undefined}
              onClick={() => handleActionClick(action, index)}
              hoverClass={action.disabled ? 'none' : 'ct-action-sheet__action--hover'}
            >
              <Text className="ct-action-sheet__action-text">{action.text}</Text>
              {action.description && (
                <Text className="ct-action-sheet__action-desc">
                  {action.description}
                </Text>
              )}
            </View>
          ))}
        </View>

        {cancelText && (
          <View className="ct-action-sheet__cancel" onClick={handleCancel}>
            <Text>{cancelText}</Text>
          </View>
        )}
      </View>
    </View>
  )
}

export default ActionSheet
export type { ActionSheetProps, ActionSheetAction } from './types'
