import { FC, useCallback, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useTouch } from '../../hooks/useTouch'

/**
 * Types
 */
import type { SwipeActionItem, SwipeActionProps } from './types'

import './index.scss'

/**
 * Constants
 */
const SWIPE_THRESHOLD = 30 // 最小滑动距离
const ACTION_WIDTH = 80 // 单个操作按钮宽度 (px)

/**
 * Main Component
 */
export const SwipeAction: FC<SwipeActionProps> = ({
  leftActions = [],
  rightActions = [],
  closeOnAction = true,
  closeOnTouchOutside = true,
  disabled = false,
  onActionsReveal,
  onClose,
  children,
  className,
}) => {
  /**
   * States
   */
  const [offset, setOffset] = useState(0)
  const [side, setSide] = useState<'left' | 'right' | null>(null)
  const [dragging, setDragging] = useState(false)

  /**
   * Refs
   */
  const startOffsetRef = useRef(0)

  /**
   * Derived Values
   */
  const leftActionsWidth = leftActions.length * ACTION_WIDTH
  const rightActionsWidth = rightActions.length * ACTION_WIDTH

  /**
   * Hooks
   */
  const touch = useTouch({ lockDirection: true })

  /**
   * Callbacks
   */
  const close = useCallback(() => {
    setOffset(0)
    setSide(null)
    onClose?.()
  }, [onClose])

  const handleTouchStart = (e: any) => {
    if (disabled) return
    touch.onTouchStart(e)
    startOffsetRef.current = offset
    setDragging(true)
  }

  const handleTouchMove = (e: any) => {
    if (disabled) return
    touch.onTouchMove(e)

    // 只处理水平滑动
    if (touch.state.direction === 'vertical') return

    const deltaX = touch.state.deltaX
    let newOffset = startOffsetRef.current + deltaX

    // 限制滑动范围
    if (newOffset > 0) {
      // 向右滑，显示左侧操作
      newOffset = leftActions.length > 0 ? Math.min(newOffset, leftActionsWidth) : 0
    } else {
      // 向左滑，显示右侧操作
      newOffset = rightActions.length > 0 ? Math.max(newOffset, -rightActionsWidth) : 0
    }

    setOffset(newOffset)
  }

  const handleTouchEnd = () => {
    if (disabled) return
    touch.onTouchEnd()
    setDragging(false)

    // 根据滑动距离决定是否展开
    if (offset > SWIPE_THRESHOLD && leftActions.length > 0) {
      setOffset(leftActionsWidth)
      setSide('left')
      onActionsReveal?.('left')
    } else if (offset < -SWIPE_THRESHOLD && rightActions.length > 0) {
      setOffset(-rightActionsWidth)
      setSide('right')
      onActionsReveal?.('right')
    } else {
      close()
    }
  }

  const handleActionClick = (action: SwipeActionItem) => {
    action.onClick?.()
    if (closeOnAction) {
      close()
    }
  }

  const handleContentClick = () => {
    if (side && closeOnTouchOutside) {
      close()
    }
  }

  /**
   * Helpers
   */
  const getActionColor = (color?: string): string => {
    if (!color) return 'var(--ct-color-primary)'
    const colorMap: Record<string, string> = {
      primary: 'var(--ct-color-primary)',
      success: 'var(--ct-color-success)',
      warning: 'var(--ct-color-warning)',
      danger: 'var(--ct-color-error)',
    }
    return colorMap[color] || color
  }

  /**
   * Render Helpers
   */
  const renderActions = (actions: SwipeActionItem[], position: 'left' | 'right') => {
    if (actions.length === 0) return null

    return (
      <View className={`ct-swipe-action__actions ct-swipe-action__actions--${position}`}>
        {actions.map((action) => (
          <View
            key={action.key}
            className="ct-swipe-action__action"
            style={{ backgroundColor: getActionColor(action.color) }}
            onClick={() => handleActionClick(action)}
          >
            <Text className="ct-swipe-action__action-text">{action.text}</Text>
          </View>
        ))}
      </View>
    )
  }

  return (
    <View
      className={classNames(
        'ct-swipe-action',
        {
          'ct-swipe-action--disabled': disabled,
          'ct-swipe-action--open': side !== null,
        },
        className
      )}
    >
      {renderActions(leftActions, 'left')}
      {renderActions(rightActions, 'right')}

      <View
        className="ct-swipe-action__content"
        style={{
          transform: `translateX(${offset}px)`,
          transition: !dragging ? 'transform 0.25s ease' : 'none',
        }}
        onClick={handleContentClick}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}
      >
        {children}
      </View>
    </View>
  )
}

export default SwipeAction
export type { SwipeActionItem, SwipeActionProps } from './types'
