import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { DividerProps } from './types'

import './index.scss'

export const Divider: FC<DividerProps> = ({
  direction = 'horizontal',
  contentPosition = 'center',
  dashed = false,
  color,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const lineStyle = color ? { borderColor: color } : undefined

  if (
    direction === 'vertical' &&
    children !== undefined &&
    children !== null &&
    process.env.NODE_ENV !== 'production'
  ) {
    // Divider vertical mode doesn't render children by design.
    console.warn('[Divider] children only apply to horizontal direction.')
  }

  /**
   * Early Returns
   */
  if (direction === 'vertical') {
    return (
      <View
        className={classNames(
          'ct-divider',
          'ct-divider--vertical',
          { 'ct-divider--dashed': dashed },
          className
        )}
        style={lineStyle}
      />
    )
  }

  return (
    <View
      className={classNames(
        'ct-divider',
        'ct-divider--horizontal',
        { 'ct-divider--dashed': dashed, 'ct-divider--with-content': children },
        className
      )}
    >
      <View
        className={classNames(
          'ct-divider__line',
          `ct-divider__line--${contentPosition}`
        )}
        style={lineStyle}
      />
      {children && (
        <View className="ct-divider__content">
          {typeof children === 'string' ? <Text>{children}</Text> : children}
        </View>
      )}
      {children && <View className="ct-divider__line" style={lineStyle} />}
    </View>
  )
}

export default Divider
export type { DividerProps, DividerDirection, DividerPosition } from './types'
