import { FC, useMemo } from 'react'
import { Picker } from '../picker'

/**
 * Types
 */
import type { PickerOption } from '../picker'
import type { TimePickerProps } from './types'

/**
 * Helpers
 */
const generateTimeColumns = (
  precision: 'hour' | 'minute' | 'second',
  minuteStep: number
) => {
  const columns: { options: PickerOption[] }[] = []

  const hours: PickerOption[] = []
  for (let h = 0; h < 24; h += 1) {
    hours.push({ label: `${h.toString().padStart(2, '0')}时`, value: h })
  }
  columns.push({ options: hours })

  if (precision === 'hour') return columns

  const minutes: PickerOption[] = []
  for (let m = 0; m < 60; m += minuteStep) {
    minutes.push({ label: `${m.toString().padStart(2, '0')}分`, value: m })
  }
  columns.push({ options: minutes })

  if (precision === 'minute') return columns

  const seconds: PickerOption[] = []
  for (let s = 0; s < 60; s += 1) {
    seconds.push({ label: `${s.toString().padStart(2, '0')}秒`, value: s })
  }
  columns.push({ options: seconds })

  return columns
}

export const TimePicker: FC<TimePickerProps> = ({
  open,
  value,
  defaultValue,
  precision = 'minute',
  title = '选择时间',
  minuteStep = 1,
  onConfirm,
  onCancel,
  onClose,
}) => {
  /**
   * Derived Values
   */
  const safeMinuteStep = Math.max(1, Math.min(59, minuteStep))

  const columns = useMemo(
    () => generateTimeColumns(precision, safeMinuteStep),
    [precision, safeMinuteStep]
  )

  /**
   * Render Helpers
   */
  const timeToValue = (time?: string) => {
    if (!time) return undefined
    const parts = time.split(':').map(Number)
    if (precision === 'hour') {
      return [parts[0]]
    }
    if (precision === 'minute') {
      return parts.slice(0, 2)
    }
    return parts
  }

  const valueToTime = (val: (string | number)[]) => {
    const [hour, minute = 0, second = 0] = val as number[]
    if (precision === 'hour') {
      return `${hour.toString().padStart(2, '0')}`
    }
    if (precision === 'minute') {
      return `${hour.toString().padStart(2, '0')}:${minute
        .toString()
        .padStart(2, '0')}`
    }
    return `${hour.toString().padStart(2, '0')}:${minute
      .toString()
      .padStart(2, '0')}:${second.toString().padStart(2, '0')}`
  }

  /**
   * Callbacks
   */
  const handleConfirm = (val: (string | number)[]) => {
    onConfirm?.(valueToTime(val))
  }

  return (
    <Picker
      open={open}
      title={title}
      columns={columns}
      value={timeToValue(value)}
      defaultValue={timeToValue(defaultValue ?? (precision === 'hour' ? '00' : '00:00'))}
      onConfirm={handleConfirm}
      onCancel={onCancel}
      onClose={onClose}
    />
  )
}

export default TimePicker
export type { TimePickerProps } from './types'
