import { FC, useEffect, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { NavBarProps } from './types'

import './index.scss'

export const NavBar: FC<NavBarProps> = ({
  title,
  left,
  right,
  showBack = true,
  onBack,
  fixed = false,
  bordered = true,
  transparent = false,
  backgroundColor,
  color,
  placeholder = true,
  className,
}) => {
  /**
   * States
   */
  const [statusBarHeight, setStatusBarHeight] = useState(0)
  const [navBarHeight, setNavBarHeight] = useState(44)

  /**
   * Callbacks
   */
  const handleBack = () => {
    if (onBack) {
      onBack()
      return
    }
    Taro.navigateBack()
  }

  /**
   * Effects
   */
  useEffect(() => {
    const systemInfo = Taro.getSystemInfoSync()
    setStatusBarHeight(systemInfo.statusBarHeight || 0)

    if (process.env.TARO_ENV === 'weapp') {
      const menuButton = Taro.getMenuButtonBoundingClientRect()
      const navHeight =
        (menuButton.top - (systemInfo.statusBarHeight || 0)) * 2 +
        menuButton.height
      setNavBarHeight(navHeight)
    }
  }, [])

  /**
   * Derived Values
   */
  const navStyle: Record<string, string> = {
    paddingTop: `${statusBarHeight}px`,
  }

  if (transparent) {
    navStyle.backgroundColor = 'transparent'
  } else if (backgroundColor) {
    navStyle.backgroundColor = backgroundColor
  }

  if (color) {
    navStyle.color = color
  }

  const contentStyle = {
    height: `${navBarHeight}px`,
  }

  /**
   * Render Helpers
   */
  const renderNavBar = () => (
    <View
      className={classNames(
        'ct-navbar',
        {
          'ct-navbar--fixed': fixed,
          'ct-navbar--bordered': bordered && !transparent,
          'ct-navbar--transparent': transparent,
        },
        className,
      )}
      style={navStyle}
    >
      <View className="ct-navbar__content" style={contentStyle}>
        <View className="ct-navbar__left">
          {left ||
            (showBack && (
              <View className="ct-navbar__back" onClick={handleBack}>
                <Icon
                  name="arrow-left"
                  size={44}
                  color={color || 'var(--ct-color-text-primary)'}
                />
              </View>
            ))}
        </View>

        <View className="ct-navbar__title">
          {typeof title === 'string' ? <Text>{title}</Text> : title}
        </View>

        <View className="ct-navbar__right">{right}</View>
      </View>
    </View>
  )

  if (fixed && placeholder) {
    return (
      <>
        {renderNavBar()}
        <View style={{ height: `${statusBarHeight + navBarHeight}px` }} />
      </>
    )
  }

  return renderNavBar()
}

export default NavBar
export type { NavBarProps } from './types'
