import { FC } from 'react'
import { Image, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'
import { Loading } from '../loading'

/**
 * Types
 */
import type { UploadFile, UploadProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const Upload: FC<UploadProps> = ({
  fileList: propFileList,
  defaultFileList = [],
  accept = 'image',
  maxCount = 9,
  maxSize = 10240,
  multiple = true,
  disabled = false,
  preview = true,
  deletable = true,
  url,
  headers,
  data,
  name = 'file',
  customUpload,
  onChange,
  onBeforeUpload,
  onRemove,
  onPreview,
  className,
}) => {
  /**
   * Hooks
   */
  const [fileList, setFileList] = useControllable({
    value: propFileList,
    defaultValue: defaultFileList,
    onChange,
  })

  /**
   * Derived Values
   */
  const canUpload = !disabled && fileList.length < maxCount

  /**
   * Callbacks
   */
  const updateFile = (uid: string, patch: Partial<UploadFile>) => {
    const next = fileList.map((item) =>
      item.uid === uid ? { ...item, ...patch } : item
    )
    setFileList(next)
  }

  const uploadFile = async (file: UploadFile) => {
    if (onBeforeUpload) {
      const allow = await onBeforeUpload(file.raw ?? file)
      if (allow === false) {
        updateFile(file.uid, {
          status: 'error',
          message: '上传已取消',
        })
        return
      }
    }

    if (customUpload) {
      try {
        const uploadedUrl = await customUpload(file)
        updateFile(file.uid, { status: 'done', url: uploadedUrl })
      } catch (error) {
        updateFile(file.uid, {
          status: 'error',
          message: '上传失败',
        })
      }
      return
    }

    if (!url) {
      updateFile(file.uid, {
        status: 'error',
        message: '缺少上传地址',
      })
      return
    }

    const resolveErrorMessage = (responseData: any) => {
      if (!responseData) return undefined
      if (typeof responseData === 'string') {
        try {
          const parsed = JSON.parse(responseData)
          return parsed?.message || parsed?.error || responseData
        } catch (error) {
          return responseData
        }
      }
      if (typeof responseData === 'object') {
        return responseData.message || responseData.error
      }
      return undefined
    }

    try {
      const res: any = await new Promise((resolve, reject) => {
        const uploadTask: any = Taro.uploadFile({
          url,
          filePath: file.url || '',
          name,
          header: headers,
          formData: data,
          success: resolve,
          fail: reject,
        })

        uploadTask?.onProgressUpdate?.((progress: any) => {
          updateFile(file.uid, {
            percent: progress?.progress ?? progress?.percent ?? 0,
          })
        })
      })

      if (res?.statusCode && res.statusCode >= 400) {
        updateFile(file.uid, {
          status: 'error',
          message: resolveErrorMessage(res.data) || '上传失败',
        })
        return
      }
      updateFile(file.uid, { status: 'done', percent: 100 })
    } catch (error) {
      updateFile(file.uid, { status: 'error', message: '上传失败' })
    }
  }

  const handleChoose = async () => {
    if (disabled || fileList.length >= maxCount) return

    const count = multiple ? maxCount - fileList.length : 1

    try {
      let rawFiles: Array<{ path: string; size?: number; name?: string }> = []

      if (accept === 'video') {
        const res = await Taro.chooseVideo({ sourceType: ['album', 'camera'] })
        rawFiles = [
          {
            path: res.tempFilePath,
            size: res.size,
            name: res.tempFilePath?.split('/').pop(),
          },
        ]
      } else if (accept === 'all' && (Taro as any).chooseMessageFile) {
        const res = await (Taro as any).chooseMessageFile({
          count,
          type: 'file',
        })
        rawFiles = (res?.tempFiles || []).map((file: any) => ({
          path: file.path,
          size: file.size,
          name: file.name,
        }))
      } else {
        const res = await Taro.chooseImage({
          count,
          sizeType: ['compressed'],
          sourceType: ['album', 'camera'],
        })
        rawFiles = (res.tempFiles || []).map((file: any) => ({
          path: file.path,
          size: file.size,
          name: file.originalFileObj?.name,
        }))
        if (!rawFiles.length && res.tempFilePaths?.length) {
          rawFiles = res.tempFilePaths.map((path: string) => ({ path }))
        }
      }

      const newFiles: UploadFile[] = rawFiles.map((file, index) => ({
        uid: `${Date.now()}-${index}`,
        url: file.path,
        name: file.name,
        size: file.size ? Math.round(file.size / 1024) : undefined,
        raw: file,
        status: 'uploading',
        percent: 0,
      }))

      setFileList([...fileList, ...newFiles])

      newFiles.forEach((file) => {
        const isOversize =
          maxSize && file.size !== undefined && file.size > maxSize
        if (isOversize) {
          updateFile(file.uid, {
            status: 'error',
            message: `文件大小超过 ${maxSize}KB`,
          })
          return
        }
        uploadFile(file)
      })
    } catch (error) {
      // user canceled
    }
  }

  const handleRemove = async (file: UploadFile, index: number) => {
    if (onRemove) {
      const result = await onRemove(file, index)
      if (result === false) return
    }

    const next = [...fileList]
    next.splice(index, 1)
    setFileList(next)
  }

  const handlePreview = (file: UploadFile) => {
    if (!preview) return
    onPreview?.(file)
  }

  return (
    <View className={classNames('ct-upload', className)}>
      {fileList.map((file, index) => (
        <View key={file.uid} className="ct-upload__item">
          <Image
            className="ct-upload__image"
            src={file.url || ''}
            mode="aspectFill"
            onClick={() => handlePreview(file)}
          />

          {file.status === 'uploading' && (
            <View className="ct-upload__mask">
              <Loading type="spinner" size="sm" color="#fff" />
            </View>
          )}

          {file.status === 'error' && (
            <View className="ct-upload__mask ct-upload__mask--error">
              <Icon name="close-circle" size={48} color="#fff" />
              <Text className="ct-upload__error">
                {file.message || '上传失败'}
              </Text>
            </View>
          )}

          {deletable && !disabled && (
            <View
              className="ct-upload__delete"
              onClick={() => handleRemove(file, index)}
            >
              <Icon name="close" size={24} color="#fff" />
            </View>
          )}
        </View>
      ))}

      {canUpload && (
        <View className="ct-upload__trigger" onClick={handleChoose}>
          <Icon name="plus" size={48} color="var(--ct-color-text-quaternary)" />
        </View>
      )}
    </View>
  )
}

export default Upload
export type { UploadFile, UploadProps } from './types'
