import { FC } from 'react'
import classNames from 'classnames'
import { Collapse } from '../collapse'

/**
 * Types
 */
import type { AccordionProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const Accordion: FC<AccordionProps> = ({
  items,
  activeKey,
  defaultActiveKey,
  onChange,
  bordered = true,
  className,
}) => {
  return (
    <Collapse
      activeKey={activeKey}
      defaultActiveKey={defaultActiveKey}
      accordion
      onChange={(key) => onChange?.(key as string)}
      bordered={bordered}
      className={classNames('ct-accordion', className)}
    >
      {items.map((item) => (
        <Collapse.Panel key={item.key} title={item.title} disabled={item.disabled}>
          {item.content}
        </Collapse.Panel>
      ))}
    </Collapse>
  )
}

export default Accordion
export type { AccordionItem, AccordionProps } from './types'
