import { FC, useEffect, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { NoticeBarProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const NoticeBar: FC<NoticeBarProps> = ({
  content,
  mode,
  icon,
  scrollable = false,
  speed = 60,
  delay = 1000,
  backgroundColor,
  color,
  open: propOpen,
  defaultOpen = true,
  visible: propVisible,
  onClose,
  onClick,
  className,
}) => {
  /**
   * Derived Values
   */
  const mergedOpen = propOpen ?? propVisible

  /**
   * States
   */
  const [innerOpen, setInnerOpen] = useState(mergedOpen ?? defaultOpen)
  const [offset, setOffset] = useState(0)
  const [contentWidth, setContentWidth] = useState(0)
  const [wrapperWidth, setWrapperWidth] = useState(0)

  /**
   * Refs
   */
  const wrapperId = useRef(`notice-bar-wrapper-${Date.now()}`)
  const textId = useRef(`notice-bar-text-${Date.now()}`)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const delayRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  /**
   * Derived Values
   */
  const isControlled = mergedOpen !== undefined
  const open = isControlled ? mergedOpen : innerOpen

  /**
   * Callbacks
   */
  const handleClose = () => {
    if (!isControlled) {
      setInnerOpen(false)
    }
    onClose?.()
  }

  const clearTimers = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current)
      timerRef.current = null
    }
    if (delayRef.current) {
      clearTimeout(delayRef.current)
      delayRef.current = null
    }
  }

  const measureWidths = () => {
    if (!scrollable || !open) return
    Taro.nextTick(() => {
      const query = Taro.createSelectorQuery()
      query.select(`#${wrapperId.current}`).boundingClientRect()
      query.select(`#${textId.current}`).boundingClientRect()
      query.exec((res) => {
        const wrapperRect = res[0]
        const textRect = res[1]
        if (!wrapperRect || !textRect) return
        setWrapperWidth(wrapperRect.width)
        setContentWidth(textRect.width)
      })
    })
  }

  /**
   * Effects
   */
  useEffect(() => {
    measureWidths()
  }, [content, icon, scrollable, open])

  useEffect(() => {
    if (!scrollable || !open) return undefined
    const handleResize = () => measureWidths()
    if (Taro.onWindowResize) {
      Taro.onWindowResize(handleResize)
      return () => {
        Taro.offWindowResize?.(handleResize)
      }
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('resize', handleResize)
      return () => window.removeEventListener('resize', handleResize)
    }
    return undefined
  }, [scrollable, open])

  useEffect(() => {
    if (!scrollable || !open) {
      clearTimers()
      setOffset(0)
      return
    }

    if (contentWidth <= wrapperWidth) {
      clearTimers()
      setOffset(0)
      return
    }

    clearTimers()
    setOffset(wrapperWidth)

    delayRef.current = setTimeout(() => {
      const frameMs = 16
      const step = (speed * frameMs) / 1000
      timerRef.current = setInterval(() => {
        setOffset((prev) => {
          const next = prev - step
          if (next <= -contentWidth) {
            return wrapperWidth
          }
          return next
        })
      }, frameMs)
    }, delay)

    return clearTimers
  }, [contentWidth, delay, scrollable, speed, open, wrapperWidth])

  /**
   * Early Returns
   */
  if (!open) return null

  return (
    <View
      className={classNames('ct-notice-bar', className)}
      style={{ backgroundColor, color }}
      onClick={mode !== 'closeable' ? onClick : undefined}
    >
      {icon && <View className="ct-notice-bar__icon">{icon}</View>}

      <View className="ct-notice-bar__content" id={wrapperId.current}>
        <View
          id={textId.current}
          className={classNames('ct-notice-bar__text', {
            'ct-notice-bar__text--scrollable': scrollable,
          })}
          style={
            scrollable ? { transform: `translateX(${offset}px)` } : undefined
          }
        >
          <Text>{content}</Text>
        </View>
      </View>

      {mode === 'closeable' && (
        <View
          className="ct-notice-bar__close"
          hoverClass="ct-clickable--hover"
          onClick={handleClose}
        >
          <Icon name="close" size={32} />
        </View>
      )}

      {mode === 'link' && (
        <View
          className="ct-notice-bar__action"
          hoverClass="ct-clickable--hover"
          onClick={onClick}
        >
          <Icon name="arrow-right" size={32} />
        </View>
      )}
    </View>
  )
}

export default NoticeBar
export type { NoticeBarMode, NoticeBarProps } from './types'
