import {
  Children,
  FC,
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useRef,
  useState,
} from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { CollapsePanelProps, CollapseProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface CollapseContextValue {
  activeKeys: string[]
  onToggle: (key: string) => void
}

interface CollapsePanelInternalProps extends CollapsePanelProps {
  __key?: string
}

type CollapseComponent = FC<CollapseProps> & {
  Panel: FC<CollapsePanelProps>
}

/**
 * Context
 */
const CollapseContext = createContext<CollapseContextValue | null>(null)

/**
 * Helpers
 */
const normalizeKeys = (keys: string | string[] | undefined): string[] => {
  if (!keys) return []
  return Array.isArray(keys) ? keys : [keys]
}

/**
 * Sub Components
 */
export const CollapsePanel: FC<CollapsePanelInternalProps> = ({
  title,
  extra,
  disabled = false,
  children,
  className,
  __key,
}) => {
  /**
   * Hooks
   */
  const context = useContext(CollapseContext)

  /**
   * States
   */
  const [contentHeight, setContentHeight] = useState(0)

  /**
   * Refs
   */
  const contentId = useRef(`collapse-content-${Date.now()}`)

  /**
   * Early Returns
   */
  if (!context || !__key) return null

  /**
   * Derived Values
   */
  const { activeKeys, onToggle } = context
  const isExpanded = activeKeys.includes(__key)

  /**
   * Effects
   */
  useEffect(() => {
    if (!isExpanded) return

    Taro.nextTick(() => {
      const query = Taro.createSelectorQuery()
      query.select(`#${contentId.current}`).boundingClientRect()
      query.exec((res) => {
        if (res[0]) {
          setContentHeight(res[0].height)
        }
      })
    })
  }, [children, isExpanded])

  /**
   * Callbacks
   */
  const handleClick = () => {
    if (!disabled) {
      onToggle(__key)
    }
  }

  return (
    <View
      className={classNames(
        'ct-collapse-panel',
        {
          'ct-collapse-panel--expanded': isExpanded,
          'ct-collapse-panel--disabled': disabled,
        },
        className,
      )}
    >
      <View className="ct-collapse-panel__header" onClick={handleClick}>
        <View className="ct-collapse-panel__title">
          {typeof title === 'string' ? <Text>{title}</Text> : title}
        </View>
        {extra && <View className="ct-collapse-panel__extra">{extra}</View>}
        <Icon
          name="chevron-down"
          size={32}
          className={classNames('ct-collapse-panel__arrow', {
            'ct-collapse-panel__arrow--expanded': isExpanded,
          })}
        />
      </View>

      <View
        className="ct-collapse-panel__content-wrapper"
        style={{ height: isExpanded ? `${contentHeight}px` : '0' }}
      >
        <View id={contentId.current} className="ct-collapse-panel__content">
          {children}
        </View>
      </View>
    </View>
  )
}

/**
 * Main Component
 */
export const Collapse: CollapseComponent = ({
  activeKey,
  defaultActiveKey = [],
  accordion = false,
  onChange,
  bordered = true,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [activeKeys, setActiveKeys] = useControllable({
    value: activeKey !== undefined ? normalizeKeys(activeKey) : undefined,
    defaultValue: normalizeKeys(defaultActiveKey),
    onChange: (keys) => {
      onChange?.(accordion ? keys[0] || '' : keys)
    },
  })

  /**
   * Callbacks
   */
  const handleToggle = (key: string) => {
    let newKeys: string[]

    if (accordion) {
      newKeys = activeKeys.includes(key) ? [] : [key]
    } else {
      newKeys = activeKeys.includes(key)
        ? activeKeys.filter((current) => current !== key)
        : [...activeKeys, key]
    }

    setActiveKeys(newKeys)
  }

  /**
   * Render Helpers
   */
  const renderChildren = () =>
    Children.map(children, (child, index) => {
      if (!isValidElement(child)) return child
      const resolvedKey =
        child.key !== null && child.key !== undefined
          ? String(child.key)
          : String(index)
      if (
        child.type === CollapsePanel &&
        (child.key === null || child.key === undefined) &&
        process.env.NODE_ENV !== 'production'
      ) {
        console.warn('[Collapse] Each Collapse.Panel should have a stable key.')
      }
      if (child.type !== CollapsePanel) return child
      return cloneElement(child, {
        __key: resolvedKey,
        key: resolvedKey,
      } as any)
    })

  return (
    <CollapseContext.Provider value={{ activeKeys, onToggle: handleToggle }}>
      <View
        className={classNames(
          'ct-collapse',
          {
            'ct-collapse--bordered': bordered,
          },
          className,
        )}
      >
        {renderChildren()}
      </View>
    </CollapseContext.Provider>
  )
}

Collapse.Panel = CollapsePanel as FC<CollapsePanelProps>

export default Collapse
export type { CollapsePanelProps, CollapseProps } from './types'
