import { FC, createContext, useContext } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { RadioGroupProps, RadioProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface RadioContextValue {
  value?: string | number
  disabled?: boolean
  onChange?: (val: string | number) => void
}

type RadioComponent = FC<RadioProps> & {
  Group: FC<RadioGroupProps>
}

/**
 * Context
 */
const RadioContext = createContext<RadioContextValue>({})

export const Radio: RadioComponent = ({
  checked: propChecked,
  defaultChecked = false,
  disabled = false,
  value,
  onChange,
  iconPosition = 'left',
  checkedColor,
  className,
  children,
}) => {
  /**
   * Hooks
   */
  const ctx = useContext(RadioContext)

  /**
   * Derived Values
   */
  const isGroupMode = ctx.value !== undefined || ctx.onChange !== undefined
  const isChecked = isGroupMode ? ctx.value === value : propChecked

  const [checked, setChecked] = useControllable({
    value: isChecked,
    defaultValue: defaultChecked,
    onChange,
  })

  const isDisabled = disabled || ctx.disabled
  const iconStyle = checkedColor && checked ? { borderColor: checkedColor } : undefined
  const dotStyle = checkedColor && checked ? { backgroundColor: checkedColor } : undefined

  /**
   * Callbacks
   */
  const handleClick = () => {
    if (isDisabled || checked) return

    if (isGroupMode) {
      if (value === undefined) {
        if (process.env.NODE_ENV !== 'production') {
          console.warn('[Radio] value is required when used inside Radio.Group.')
        }
        return
      }
      ctx.onChange?.(value)
    } else {
      setChecked(true)
    }
  }

  return (
    <View
      className={classNames(
        'ct-radio',
        {
          'ct-radio--checked': checked,
          'ct-radio--disabled': isDisabled,
          'ct-radio--right': iconPosition === 'right',
        },
        className
      )}
      hoverClass={isDisabled ? 'none' : 'ct-clickable--hover'}
      onClick={handleClick}
    >
      <View className="ct-radio__icon" style={iconStyle}>
        {checked && <View className="ct-radio__dot" style={dotStyle} />}
      </View>
      {children && (
        <View className="ct-radio__label">
          {typeof children === 'string' ? <Text>{children}</Text> : children}
        </View>
      )}
    </View>
  )
}

export const RadioGroup: FC<RadioGroupProps> = ({
  value: propValue,
  defaultValue,
  disabled = false,
  direction = 'vertical',
  onChange,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable<string | number | undefined>({
    value: propValue,
    defaultValue,
    onChange: onChange as (value: string | number | undefined) => void,
  })

  /**
   * Callbacks
   */
  const handleChange = (val: string | number) => {
    setValue(val)
  }

  return (
    <RadioContext.Provider value={{ value, disabled, onChange: handleChange }}>
      <View
        className={classNames(
          'ct-radio-group',
          `ct-radio-group--${direction}`,
          className
        )}
      >
        {children}
      </View>
    </RadioContext.Provider>
  )
}

Radio.Group = RadioGroup

export default Radio
export type { RadioProps, RadioGroupProps } from './types'
