import { FC } from 'react'
import { Image, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'

/**
 * Types
 */
import type { ProgressProps, ProgressStatus } from './types'

import './index.scss'

/**
 * Constants
 */
const STATUS_COLOR: Record<ProgressStatus, string> = {
  normal: 'var(--ct-color-primary)',
  success: 'var(--ct-color-success)',
  error: 'var(--ct-color-error)',
}

const STATUS_COLOR_FALLBACK: Record<ProgressStatus, string> = {
  normal: '#3b82f6',
  success: '#22c55e',
  error: '#ef4444',
}

export const Progress: FC<ProgressProps> = ({
  percent,
  type = 'line',
  status = 'normal',
  showText = true,
  format,
  trackColor,
  fillColor,
  strokeWidth = 8,
  size = 200,
  className,
}) => {
  /**
   * Derived Values
   */
  const validPercent = Math.max(0, Math.min(100, percent))
  const color = fillColor || STATUS_COLOR[status]
  const isFillCssVar = typeof fillColor === 'string' && fillColor.startsWith('var(')
  const svgColor = isFillCssVar
    ? STATUS_COLOR_FALLBACK[status]
    : fillColor || STATUS_COLOR_FALLBACK[status]
  const displayText = format ? format(validPercent) : `${validPercent}%`
  const resolvedTrackColor = trackColor ?? 'var(--ct-color-border)'
  const isTrackCssVar = typeof trackColor === 'string' && trackColor.startsWith('var(')
  const svgTrackColor = isTrackCssVar ? '#e5e7eb' : trackColor ?? '#e5e7eb'

  /**
   * Render Helpers
   */
  if (type === 'circle') {
    const radius = (size - strokeWidth) / 2
    const circumference = 2 * Math.PI * radius
    const offset = circumference * (1 - validPercent / 100)
    const env = Taro.getEnv?.()
    const useInlineSvg = env === Taro.ENV_TYPE.WEB
    const svgMarkup = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}"><circle cx="${size / 2}" cy="${size / 2}" r="${radius}" stroke="${svgTrackColor}" stroke-width="${strokeWidth}" fill="none"/><circle cx="${size / 2}" cy="${size / 2}" r="${radius}" stroke="${svgColor}" stroke-width="${strokeWidth}" stroke-dasharray="${circumference}" stroke-dashoffset="${offset}" stroke-linecap="round" fill="none"/></svg>`
    const svgDataUri = `data:image/svg+xml;utf8,${encodeURIComponent(svgMarkup)}`

    return (
      <View className={classNames('ct-progress', 'ct-progress--circle', className)}>
        {useInlineSvg ? (
          <svg
            viewBox={`0 0 ${size} ${size}`}
            style={{ width: `${size}rpx`, height: `${size}rpx` }}
          >
            <circle
              className="ct-progress__track"
              cx={size / 2}
              cy={size / 2}
              r={radius}
              strokeWidth={strokeWidth}
              style={{ stroke: resolvedTrackColor }}
            />
            <circle
              className="ct-progress__fill"
              cx={size / 2}
              cy={size / 2}
              r={radius}
              strokeWidth={strokeWidth}
              strokeDasharray={circumference}
              strokeDashoffset={offset}
              style={{ stroke: color }}
            />
          </svg>
        ) : (
          <Image
            src={svgDataUri}
            mode="aspectFit"
            style={{ width: `${size}rpx`, height: `${size}rpx` }}
          />
        )}
        {showText && (
          <View className="ct-progress__text">
            <Text>{displayText}</Text>
          </View>
        )}
      </View>
    )
  }

  return (
    <View className={classNames('ct-progress', 'ct-progress--line', className)}>
      <View
        className="ct-progress__track"
        style={{
          height: `${strokeWidth}rpx`,
          backgroundColor: resolvedTrackColor,
        }}
      >
        <View
          className="ct-progress__fill"
          style={{
            width: `${validPercent}%`,
            backgroundColor: color,
          }}
        />
      </View>
      {showText && (
        <View className="ct-progress__text">
          <Text>{displayText}</Text>
        </View>
      )}
    </View>
  )
}

export default Progress
export type { ProgressProps, ProgressType, ProgressStatus } from './types'
