import type { FC } from 'react'
import { hideToast, showToast } from './imperative'
import { ToastView } from './toast'

/**
 * Types
 */
import type { ToastProps, ToastShowOptions } from './types'

/**
 * Internal Types
 */
export interface ToastComponent extends FC<ToastProps> {
  show: (options: ToastShowOptions | string) => void
  success: (content: string, duration?: number) => void
  error: (content: string, duration?: number) => void
  loading: (content?: string) => void
  hide: () => void
}

export const Toast = ToastView as ToastComponent

Toast.show = showToast
Toast.success = (content: string, duration?: number) => {
  showToast({ content, type: 'success', duration })
}
Toast.error = (content: string, duration?: number) => {
  showToast({ content, type: 'error', duration })
}
Toast.loading = (content: string = '加载中...') => {
  showToast({ content, type: 'loading', duration: 0, mask: true })
}
Toast.hide = hideToast

export default Toast
export type { ToastProps, ToastType, ToastPosition, ToastShowOptions } from './types'
