import { FC, useEffect, useState } from 'react'
import { View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'

/**
 * Types
 */
import type { SafeAreaProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const SafeArea: FC<SafeAreaProps> = ({
  position,
  children,
  className,
}) => {
  /**
   * States
   */
  const [height, setHeight] = useState(0)

  /**
   * Effects
   */
  useEffect(() => {
    const systemInfo = Taro.getSystemInfoSync()

    if (position === 'top') {
      setHeight(systemInfo.statusBarHeight || 0)
      return
    }

    const screenHeight = systemInfo.screenHeight
    const safeAreaBottom = systemInfo.safeArea?.bottom || screenHeight
    setHeight(screenHeight - safeAreaBottom)
  }, [position])

  return (
    <View
      className={classNames(
        'ct-safe-area',
        `ct-safe-area--${position}`,
        className,
      )}
      style={{ height: `${height}px` }}
    >
      {children}
    </View>
  )
}

export default SafeArea
export type { SafeAreaPosition, SafeAreaProps } from './types'
