import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Loading } from '../loading'

/**
 * Types
 */
import type { SwitchProps } from './types'

import './index.scss'

export const Switch: FC<SwitchProps> = ({
  checked: propChecked,
  defaultChecked = false,
  disabled = false,
  loading = false,
  size = 'md',
  checkedColor,
  uncheckedColor,
  checkedText,
  uncheckedText,
  onChange,
  className,
}) => {
  /**
   * Hooks
   */
  const [checked, setChecked] = useControllable({
    value: propChecked,
    defaultValue: defaultChecked,
    onChange,
  })

  /**
   * Derived Values
   */
  const isDisabled = disabled || loading
  const trackStyle = checked
    ? checkedColor
      ? { backgroundColor: checkedColor }
      : undefined
    : uncheckedColor
    ? { backgroundColor: uncheckedColor }
    : undefined
  const hasText = !!(checkedText || uncheckedText)

  /**
   * Callbacks
   */
  const handleClick = () => {
    if (isDisabled) return
    setChecked(!checked)
  }

  return (
    <View
      className={classNames(
        'ct-switch',
        `ct-switch--${size}`,
        {
          'ct-switch--checked': checked,
          'ct-switch--disabled': isDisabled,
          'ct-switch--loading': loading,
          'ct-switch--textless': !hasText,
        },
        className
      )}
      hoverClass={isDisabled ? 'none' : 'ct-clickable--hover'}
      onClick={handleClick}
    >
      <View className="ct-switch__track" style={trackStyle}>
        {hasText && (
          <Text className="ct-switch__text">
            {checked ? checkedText : uncheckedText}
          </Text>
        )}
      </View>
      <View className="ct-switch__thumb">
        {loading && <Loading type="spinner" size="sm" />}
      </View>
    </View>
  )
}

export default Switch
export type { SwitchProps, SwitchSize } from './types'
