import { FC, useEffect, useMemo, useState } from 'react'
import { Picker } from '../picker'

/**
 * Types
 */
import type { PickerOption } from '../picker'
import type { DatePickerProps } from './types'

/**
 * Helpers
 */
const getDaysInMonth = (year: number, month: number) =>
  new Date(year, month, 0).getDate()

const generateDateColumns = (
  min: Date,
  max: Date,
  precision: 'year' | 'month' | 'day',
  currentValue?: (string | number)[]
) => {
  const columns: { options: PickerOption[] }[] = []

  const years: PickerOption[] = []
  for (let y = min.getFullYear(); y <= max.getFullYear(); y += 1) {
    years.push({ label: `${y}年`, value: y })
  }
  columns.push({ options: years })

  if (precision === 'year') return columns

  const months: PickerOption[] = []
  for (let m = 1; m <= 12; m += 1) {
    months.push({ label: `${m}月`, value: m })
  }
  columns.push({ options: months })

  if (precision === 'month') return columns

  const selectedYear =
    typeof currentValue?.[0] === 'number' ? Number(currentValue[0]) : min.getFullYear()
  const selectedMonth =
    typeof currentValue?.[1] === 'number' ? Number(currentValue[1]) : min.getMonth() + 1
  const daysInMonth = getDaysInMonth(selectedYear, selectedMonth)

  const days: PickerOption[] = []
  for (let d = 1; d <= daysInMonth; d += 1) {
    days.push({ label: `${d}日`, value: d })
  }
  columns.push({ options: days })

  return columns
}

export const DatePicker: FC<DatePickerProps> = ({
  open,
  value,
  defaultValue,
  min = new Date(1900, 0, 1),
  max = new Date(2100, 11, 31),
  precision = 'day',
  title = '选择日期',
  onConfirm,
  onCancel,
  onClose,
}) => {
  /**
   * Render Helpers
   */
  const dateToValue = (date?: Date) => {
    if (!date) return undefined
    const result: (string | number)[] = [date.getFullYear(), date.getMonth() + 1]
    if (precision === 'day') result.push(date.getDate())
    return result
  }

  /**
   * States
   */
  const [currentValue, setCurrentValue] = useState<(string | number)[] | undefined>(
    dateToValue(value ?? defaultValue ?? new Date())
  )

  /**
   * Effects
   */
  useEffect(() => {
    setCurrentValue(dateToValue(value ?? defaultValue ?? new Date()))
  }, [defaultValue, precision, value])

  /**
   * Derived Values
   */
  const columns = useMemo(
    () => generateDateColumns(min, max, precision, currentValue),
    [currentValue, min, max, precision]
  )

  /**
   * Callbacks
   */
  const handleConfirm = (val: (string | number)[]) => {
    const [year, month = 1, day = 1] = val as number[]
    const safeDay =
      precision === 'day' ? Math.min(day, getDaysInMonth(year, month)) : 1
    onConfirm?.(new Date(year, month - 1, safeDay))
  }

  return (
    <Picker
      open={open}
      title={title}
      columns={columns}
      value={dateToValue(value)}
      defaultValue={dateToValue(defaultValue ?? new Date())}
      onChange={(val) => setCurrentValue(val)}
      onConfirm={handleConfirm}
      onCancel={onCancel}
      onClose={onClose}
    />
  )
}

export default DatePicker
export type { DatePickerProps } from './types'
