import { FC, useEffect, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useTouch } from '../../hooks/useTouch'
import { px2rpx } from '../../utils/rpx'
import { Icon } from '../icon'
import { Loading } from '../loading'

/**
 * Types
 */
import type { PullRefreshProps, PullRefreshStatus } from './types'

import './index.scss'

/**
 * Main Component
 */
export const PullRefresh: FC<PullRefreshProps> = ({
  refreshing,
  onRefresh,
  threshold = 100,
  pullingText = '下拉刷新',
  loosingText = '释放刷新',
  loadingText = '加载中...',
  successText = '刷新成功',
  successDuration = 500,
  disabled = false,
  head,
  children,
  className,
}) => {
  /**
   * States
   */
  const [status, setStatus] = useState<PullRefreshStatus>('normal')
  const [pullDistance, setPullDistance] = useState(0)

  /**
   * Refs
   */
  const successTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const canPullRef = useRef(true)

  /**
   * Hooks
   */
  const touch = useTouch({ lockDirection: true })

  /**
   * Callbacks
   */
  const clearSuccessTimer = () => {
    if (successTimerRef.current) {
      clearTimeout(successTimerRef.current)
      successTimerRef.current = null
    }
  }

  const handleTouchStart = (event: any) => {
    if (disabled || refreshing) return
    touch.onTouchStart(event)
    Taro.createSelectorQuery()
      .selectViewport()
      .scrollOffset()
      .exec((res) => {
        const scrollTop = res?.[0]?.scrollTop ?? 0
        canPullRef.current = scrollTop <= 0
        if (!canPullRef.current) {
          setPullDistance(0)
          setStatus('normal')
        }
      })
  }

  const handleTouchMove = (event: any) => {
    if (disabled || refreshing) return
    if (!canPullRef.current) return
    touch.onTouchMove(event)
    const { direction, deltaY } = touch.state
    if (direction && direction !== 'vertical') return
    if (deltaY <= 0) {
      setPullDistance(0)
      setStatus('normal')
      return
    }

    const distance = px2rpx(deltaY)
    const damped = Math.min(distance, threshold * 1.6)
    setPullDistance(damped)
    setStatus(damped >= threshold ? 'loosing' : 'pulling')
  }

  const handleTouchEnd = () => {
    if (disabled || refreshing) return
    touch.onTouchEnd()
    if (status === 'loosing') {
      setStatus('loading')
      setPullDistance(threshold)
      onRefresh?.()
      return
    }
    setStatus('normal')
    setPullDistance(0)
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (refreshing) {
      clearSuccessTimer()
      setStatus('loading')
      setPullDistance(threshold)
      return
    }

    if (status === 'loading') {
      if (successDuration > 0) {
        setStatus('success')
        setPullDistance(threshold)
        successTimerRef.current = setTimeout(() => {
          setStatus('normal')
          setPullDistance(0)
        }, successDuration)
      } else {
        setStatus('normal')
        setPullDistance(0)
      }
    }
  }, [refreshing, status, successDuration, threshold])

  useEffect(() => {
    return () => {
      clearSuccessTimer()
    }
  }, [])

  /**
   * Render Helpers
   */
  const renderHead = () => {
    if (head) return head(status)

    switch (status) {
      case 'pulling':
        return (
          <View className="ct-pull-refresh__tip">
            <Icon name="arrow-down" size={32} />
            <Text>{pullingText}</Text>
          </View>
        )
      case 'loosing':
        return (
          <View className="ct-pull-refresh__tip">
            <Icon name="arrow-up" size={32} />
            <Text>{loosingText}</Text>
          </View>
        )
      case 'loading':
        return (
          <View className="ct-pull-refresh__tip">
            <Loading type="spinner" size="sm" />
            <Text>{loadingText}</Text>
          </View>
        )
      case 'success':
        return (
          <View className="ct-pull-refresh__tip">
            <Icon name="check" size={32} />
            <Text>{successText}</Text>
          </View>
        )
      default:
        return null
    }
  }

  return (
    <View
      className={classNames('ct-pull-refresh', className)}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <View
        className="ct-pull-refresh__head"
        style={{ height: `${pullDistance}rpx` }}
      >
        {renderHead()}
      </View>
      <View className="ct-pull-refresh__content">{children}</View>
    </View>
  )
}

export default PullRefresh
export type { PullRefreshProps, PullRefreshStatus } from './types'
