import { useRef, useState } from 'react'

/**
 * Types
 */
export type TouchDirection = '' | 'horizontal' | 'vertical'

export interface TouchState {
  startX: number
  startY: number
  deltaX: number
  deltaY: number
  offsetX: number
  offsetY: number
  direction: TouchDirection
  velocity: number
  velocityX: number
  velocityY: number
  startTime: number
  isLocked: boolean
}

export interface UseTouchOptions {
  lockDirection?: boolean
  threshold?: number
  velocityThreshold?: number
}

/**
 * Constants
 */
const initialState: TouchState = {
  startX: 0,
  startY: 0,
  deltaX: 0,
  deltaY: 0,
  offsetX: 0,
  offsetY: 0,
  direction: '',
  velocity: 0,
  velocityX: 0,
  velocityY: 0,
  startTime: 0,
  isLocked: false,
}

/**
 * Main Hook
 */
export function useTouch(options: UseTouchOptions = {}) {
  const {
    lockDirection = false,
    threshold = 10,
    velocityThreshold = 0.3,
  } = options

  /**
   * States
   */
  const [state, setState] = useState<TouchState>(initialState)

  /**
   * Refs
   */
  const touchRef = useRef<TouchState>(initialState)

  /**
   * Callbacks
   */
  const onTouchStart = (event: any) => {
    const touch = event.touches[0]
    const now = Date.now()

    touchRef.current = {
      ...touchRef.current,
      startX: touch.clientX,
      startY: touch.clientY,
      startTime: now,
      direction: '',
      isLocked: false,
    }
    setState(touchRef.current)
  }

  const onTouchMove = (event: any) => {
    const touch = event.touches[0]
    const now = Date.now()
    const deltaX = touch.clientX - touchRef.current.startX
    const deltaY = touch.clientY - touchRef.current.startY
    const offsetX = Math.abs(deltaX)
    const offsetY = Math.abs(deltaY)
    const duration = now - touchRef.current.startTime

    const velocityX = duration > 0 ? deltaX / duration : 0
    const velocityY = duration > 0 ? deltaY / duration : 0
    const velocity = Math.sqrt(velocityX ** 2 + velocityY ** 2)

    let direction = touchRef.current.direction
    let isLocked = touchRef.current.isLocked

    if (!direction && (offsetX > threshold || offsetY > threshold)) {
      direction = offsetX > offsetY ? 'horizontal' : 'vertical'
      if (lockDirection) {
        isLocked = true
      }
    }

    touchRef.current = {
      ...touchRef.current,
      deltaX,
      deltaY,
      offsetX,
      offsetY,
      direction,
      velocity,
      velocityX,
      velocityY,
      isLocked,
    }
    setState(touchRef.current)
  }

  const onTouchEnd = () => {
    // keep final state for swipe detection
  }

  const isSwipe = (direction: 'left' | 'right' | 'up' | 'down') => {
    const { velocityX, velocityY, deltaX, deltaY } = touchRef.current

    switch (direction) {
      case 'left':
        return velocityX < -velocityThreshold && deltaX < 0
      case 'right':
        return velocityX > velocityThreshold && deltaX > 0
      case 'up':
        return velocityY < -velocityThreshold && deltaY < 0
      case 'down':
        return velocityY > velocityThreshold && deltaY > 0
      default:
        return false
    }
  }

  const reset = () => {
    touchRef.current = { ...initialState }
    setState(touchRef.current)
  }

  return {
    state,
    reset,
    onTouchStart,
    onTouchMove,
    onTouchEnd,
    isSwipe,
  }
}
