import {
  Children,
  FC,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useState,
} from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { OVERLAY_ANIMATION_DURATION } from '../../constants/animation'
import { useControllable } from '../../hooks/useControllable'
import { Button } from '../button'
import { Icon } from '../icon'

/**
 * Types
 */
import type {
  ModalBodyProps,
  ModalContentProps,
  ModalFooterProps,
  ModalHeaderProps,
  ModalProps,
} from './types'

import './index.scss'

/**
 * Context
 */
const ModalContext = createContext<{ onClose?: () => void }>({})

/**
 * Sub Components
 */
const ModalContent: FC<ModalContentProps> = ({ children, className }) => (
  <View className={classNames('ct-modal__content', className)}>{children}</View>
)

const ModalHeader: FC<ModalHeaderProps> = ({ children, closable = true, onClose }) => {
  const ctx = useContext(ModalContext)
  const handleClose = onClose || ctx.onClose

  return (
    <View className="ct-modal__header">
      <Text className="ct-modal__title">{children}</Text>
      {closable && (
        <View className="ct-modal__close" onClick={handleClose}>
          <Icon name="close" size={40} />
        </View>
      )}
    </View>
  )
}

const ModalBody: FC<ModalBodyProps> = ({ children, className }) => (
  <View className={classNames('ct-modal__body', className)}>{children}</View>
)

const ModalFooter: FC<ModalFooterProps> = ({ children, className }) => (
  <View className={classNames('ct-modal__footer', className)}>{children}</View>
)

/**
 * Main Component
 */
const Modal: FC<ModalProps> & {
  Content: typeof ModalContent
  Header: typeof ModalHeader
  Body: typeof ModalBody
  Footer: typeof ModalFooter
} = ({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  title,
  onClose,
  onConfirm,
  confirmText = '确认',
  cancelText = '取消',
  closable = true,
  closeOnOverlayClick = true,
  showFooter = true,
  footer,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [isOpen, setIsOpen] = useControllable({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })

  /**
   * States
   */
  const [visible, setVisible] = useState(false)
  const [animating, setAnimating] = useState(false)

  /**
   * Derived Values
   */
  const childArray = Children.toArray(children)
  const hasHeaderSlot = childArray.some(
    (child) => isValidElement(child) && child.type === ModalHeader
  )
  const hasBodySlot = childArray.some(
    (child) => isValidElement(child) && child.type === ModalBody
  )
  const hasFooterSlot = childArray.some(
    (child) => isValidElement(child) && child.type === ModalFooter
  )
  const hasContentSlot = childArray.some(
    (child) => isValidElement(child) && child.type === ModalContent
  )
  const isCompound = hasHeaderSlot || hasBodySlot || hasFooterSlot || hasContentSlot

  /**
   * Callbacks
   */
  const handleClose = () => {
    setIsOpen(false)
    onClose?.()
  }

  const handleOverlayClick = () => {
    if (closeOnOverlayClick) {
      handleClose()
    }
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (isOpen) {
      setVisible(true)
      Taro.nextTick(() => setAnimating(true))
    } else {
      setAnimating(false)
      const timer = setTimeout(() => setVisible(false), OVERLAY_ANIMATION_DURATION)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [isOpen])

  /**
   * Early Returns
   */
  if (!visible) return null

  return (
    <ModalContext.Provider value={{ onClose: handleClose }}>
      <View className="ct-modal" catchMove>
        <View
          className={classNames('ct-modal__mask', {
            'ct-modal__mask--visible': animating,
          })}
          onClick={handleOverlayClick}
        />
        <View
          className={classNames(
            'ct-modal__container',
            { 'ct-modal__container--visible': animating },
          className
        )}
      >
          {title && !hasHeaderSlot && (
            <View className="ct-modal__header">
              <Text className="ct-modal__title">{title}</Text>
              {closable && (
                <View className="ct-modal__close" onClick={handleClose}>
                  <Icon name="close" size={40} />
                </View>
              )}
            </View>
          )}

          {isCompound ? (
            children
          ) : (
            <View className="ct-modal__body">{children}</View>
          )}

          {showFooter && !footer && !hasFooterSlot && (
            <View className="ct-modal__footer">
              <Button variant="ghost" onClick={handleClose}>
                {cancelText}
              </Button>
              <Button variant="primary" onClick={onConfirm}>
                {confirmText}
              </Button>
            </View>
          )}

          {footer && !hasFooterSlot ? footer : null}
        </View>
      </View>
    </ModalContext.Provider>
  )
}

Modal.Content = ModalContent
Modal.Header = ModalHeader
Modal.Body = ModalBody
Modal.Footer = ModalFooter

export default Modal
export { Modal }
export type {
  ModalBodyProps,
  ModalContentProps,
  ModalFooterProps,
  ModalHeaderProps,
  ModalProps,
} from './types'
