import { useCallback, useRef, useState } from 'react'

/**
 * Types
 */
export interface UseControllableOptions<T> {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}

/**
 * Main Hook
 */
export function useControllable<T>({
  value: controlledValue,
  defaultValue,
  onChange,
}: UseControllableOptions<T>) {
  /**
   * States
   */
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue)

  /**
   * Derived Values
   */
  const isControlled = controlledValue !== undefined
  const value = isControlled ? controlledValue : uncontrolledValue

  /**
   * Refs
   */
  // 使用 ref 存储最新的值和回调，避免 useCallback 依赖导致的重建
  const stateRef = useRef({ value, onChange, isControlled })
  stateRef.current = { value, onChange, isControlled }

  /**
   * Callbacks
   */
  const setValue = useCallback((nextValue: T | ((prev: T) => T)) => {
    const { value: currentValue, onChange: currentOnChange, isControlled: currentIsControlled } = stateRef.current
    const newValue =
      typeof nextValue === 'function'
        ? (nextValue as (prev: T) => T)(currentValue)
        : nextValue

    if (!currentIsControlled) {
      setUncontrolledValue(newValue)
    }
    currentOnChange?.(newValue)
  }, [])

  return [value, setValue] as const
}
