import { FC, useMemo } from 'react'
import { View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { RateProps } from './types'

import './index.scss'

export const Rate: FC<RateProps> = ({
  value: propValue,
  defaultValue = 0,
  count = 5,
  allowHalf = false,
  allowClear = false,
  disabled = false,
  readOnly = false,
  size = 48,
  gap = 8,
  character,
  onChange,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable<number>({
    value: propValue,
    defaultValue,
    onChange,
  })

  /**
   * Derived Values
   */
  const isInteractive = !disabled && !readOnly

  const stars = useMemo(() => {
    return Array.from({ length: count }, (_, index) => {
      const starValue = index + 1
      const isFull = value >= starValue
      const isHalf = allowHalf && value >= starValue - 0.5 && value < starValue

      return {
        index,
        isFull,
        isHalf,
        isEmpty: !isFull && !isHalf,
      }
    })
  }, [count, value, allowHalf])

  /**
   * Callbacks
   */
  const handleClick = (index: number, isHalf: boolean) => {
    if (!isInteractive) return

    let newValue = isHalf ? index + 0.5 : index + 1

    if (allowClear && newValue === value) {
      newValue = 0
    }

    setValue(newValue)
  }

  /**
   * Render Helpers
   */
  const renderCharacter = (index: number, type: 'full' | 'half' | 'empty') => {
    if (character) {
      return typeof character === 'function' ? character(index) : character
    }
    return (
      <Icon
        name={type === 'empty' ? 'star' : 'star-fill'}
        size={size}
        className={classNames('ct-rate__icon', {
          'ct-rate__icon--active': type !== 'empty',
          'ct-rate__icon--half': type === 'half',
        })}
      />
    )
  }

  return (
    <View
      className={classNames(
        'ct-rate',
        {
          'ct-rate--disabled': disabled,
          'ct-rate--readonly': readOnly,
        },
        className
      )}
      style={{ gap: `${gap}rpx` }}
    >
      {stars.map((star) => (
        <View
          key={star.index}
          className={classNames('ct-rate__star', {
            'ct-rate__star--active': star.isFull || star.isHalf,
            'ct-rate__star--half': star.isHalf,
          })}
          style={{ width: `${size}rpx`, height: `${size}rpx` }}
        >
          <View className="ct-rate__star-first">
            {renderCharacter(star.index, 'empty')}
          </View>

          {(star.isFull || star.isHalf) && (
            <View
              className="ct-rate__star-second"
              style={star.isHalf ? { width: '50%' } : undefined}
            >
              {renderCharacter(star.index, star.isHalf ? 'half' : 'full')}
            </View>
          )}

          {isInteractive && (
            <>
              {allowHalf && (
                <View
                  className="ct-rate__star-half-left"
                  onClick={() => handleClick(star.index, true)}
                />
              )}
              <View
                className={allowHalf ? 'ct-rate__star-half-right' : 'ct-rate__star-full'}
                onClick={() => handleClick(star.index, false)}
              />
            </>
          )}
        </View>
      ))}
    </View>
  )
}

export default Rate
export type { RateProps } from './types'
