import { FC, useState } from 'react'
import { Input as TaroInput, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { InputProps } from './types'

import './index.scss'

export const Input: FC<InputProps> = ({
  type = 'text',
  value: propValue,
  defaultValue = '',
  placeholder,
  disabled = false,
  readOnly = false,
  maxLength,
  clearable = false,
  prefix,
  suffix,
  align = 'left',
  onChange,
  onFocus,
  onBlur,
  onClear,
  className,
}) => {
  /**
   * States
   */
  const isControlled = propValue !== undefined
  const [innerValue, setInnerValue] = useState(defaultValue)
  const value = isControlled ? propValue : innerValue
  const [focused, setFocused] = useState(false)

  /**
   * Derived Values
   */
  const showClear = clearable && value && !disabled && !readOnly

  /**
   * Callbacks
   */
  const handleInput = (e: any) => {
    if (disabled || readOnly) return
    const newValue = e.detail.value
    if (!isControlled) {
      setInnerValue(newValue)
    }
    onChange?.(newValue)
  }

  const handleFocus = (e: any) => {
    setFocused(true)
    onFocus?.(e)
  }

  const handleBlur = (e: any) => {
    setFocused(false)
    onBlur?.(e)
  }

  const handleClear = () => {
    if (!isControlled) {
      setInnerValue('')
    }
    onChange?.('')
    onClear?.()
  }

  return (
    <View
      className={classNames(
        'ct-input',
        {
          'ct-input--disabled': disabled,
          'ct-input--focused': focused,
        },
        className
      )}
    >
      {/* 前缀 */}
      {prefix && <View className="ct-input__prefix">{prefix}</View>}

      {/* 输入框容器 - 使用单独的容器包裹 */}
      <View className="ct-input__content">
        <TaroInput
          className={classNames('ct-input__inner', `ct-input__inner--${align}`)}
          type={type as any}
          value={value}
          placeholder={placeholder}
          disabled={disabled}
          maxlength={maxLength}
          onInput={handleInput}
          onFocus={handleFocus}
          onBlur={handleBlur}
          placeholderStyle="color: #cbd5e1"
        />
      </View>

      {/* 清除按钮 */}
      {showClear && (
        <View className="ct-input__clear" onClick={handleClear}>
          <Icon name="close-circle" size={32} color="#94a3b8" />
        </View>
      )}

      {/* 后缀 */}
      {suffix && <View className="ct-input__suffix">{suffix}</View>}
    </View>
  )
}

export default Input
export type { InputProps, InputType } from './types'
