import Taro from '@tarojs/taro'
import { createRoot, type Root } from 'react-dom/client'
import { ToastView } from './toast'

/**
 * Types
 */
import type { ToastProps, ToastShowOptions, ToastType } from './types'

/**
 * Constants
 */
const isH5 = process.env.TARO_ENV === 'h5'

/**
 * States
 */
let toastRoot: Root | null = null
let toastContainer: HTMLElement | null = null

/**
 * Helpers
 */
const normalizeOptions = (options: ToastShowOptions | string): ToastShowOptions =>
  typeof options === 'string' ? { content: options } : options

const resolveTaroIcon = (type?: ToastType) => {
  if (type === 'success') return 'success'
  if (type === 'loading') return 'loading'
  return 'none'
}

const ensureContainer = () => {
  if (toastContainer || typeof document === 'undefined') return
  toastContainer = document.createElement('div')
  document.body.appendChild(toastContainer)
  toastRoot = createRoot(toastContainer)
}

/**
 * Exports
 */
export const hideToast = () => {
  if (!isH5) {
    Taro.hideToast()
    return
  }
  if (toastRoot) {
    toastRoot.unmount()
    toastRoot = null
  }
  if (toastContainer) {
    toastContainer.remove()
    toastContainer = null
  }
}

export const showToast = (options: ToastShowOptions | string) => {
  const config = normalizeOptions(options)

  if (!isH5) {
    if (process.env.NODE_ENV !== 'production' && (config.position || config.icon)) {
      console.warn('[Toast] Non-H5 platforms only support basic icon and duration options.')
    }
    const duration = config.duration ?? 2000
    Taro.showToast({
      title: config.content,
      icon: resolveTaroIcon(config.type),
      duration,
      mask: config.mask ?? false,
    })
    if (config.onClose) {
      setTimeout(() => config.onClose?.(), duration)
    }
    return
  }

  ensureContainer()
  if (!toastRoot) return

  const handleClose = () => {
    config.onClose?.()
    hideToast()
  }

  const props: ToastProps = {
    open: true,
    content: config.content,
    type: config.type ?? 'info',
    position: config.position ?? 'center',
    duration: config.duration ?? 2000,
    icon: config.icon,
    mask: config.mask ?? false,
    onClose: handleClose,
  }

  toastRoot.render(<ToastView {...props} />)
}
